namespace {
long materialAllocationCountdown=-1;std::size_t materialFailedAllocations=0u;
struct MaterialAllocationFailure {explicit MaterialAllocationFailure(long value){materialAllocationCountdown=value;}~MaterialAllocationFailure(){materialAllocationCountdown=-1;}};
}
void* operator new(std::size_t size){
    if(materialAllocationCountdown==0){++materialFailedAllocations;throw std::bad_alloc();}
    if(materialAllocationCountdown>0)--materialAllocationCountdown;
    if(void* value=std::malloc(size?size:1u))return value;throw std::bad_alloc();
}
void* operator new[](std::size_t size){return ::operator new(size);}
void operator delete(void* value)noexcept{std::free(value);}
void operator delete[](void* value)noexcept{std::free(value);}
void operator delete(void* value,std::size_t)noexcept{std::free(value);}
void operator delete[](void* value,std::size_t)noexcept{std::free(value);}
class DxIfaceMaterialReferenceTestAccess {
public:
    static bool prepareBody(dx_iface& value,long offset,bool binary){
        value.m_dxfMaterialWriteSources.clear();value.m_dxfMaterialWriteDictionaries.clear();
        value.m_dxfMaterialWriteInspected=false;value.m_dxfMaterialWriteRequired=false;
        MaterialAllocationFailure injection(offset);return value.prepareDxfMaterialSources(DRW::AC1027,binary);
    }
    static bool materialReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view){
        const auto saved=value.m_dxfMaterialWriteInspected;value.m_dxfMaterialWriteInspected=false;
        const bool good=value.inspectDxfMaterialOutput(view);value.m_dxfMaterialWriteInspected=saved;return good;
    }
    static bool prepareVariables(dx_iface& value,long offset,bool binary){MaterialAllocationFailure injection(offset);return value.prepareDxfDictionaryVars(value.cData->sourceVersion,binary);}
    static bool prepareMLineStyles(dx_iface& value,long offset,bool binary){MaterialAllocationFailure injection(offset);return value.prepareDxfMLineStyles(value.cData->sourceVersion,binary);}
    static bool prepareMLineConsumers(dx_iface& value,long offset,bool binary){MaterialAllocationFailure injection(offset);return value.prepareDxfMLineConsumers(value.cData->sourceVersion,binary);}
    static bool prepareMLineLinetypes(dx_iface& value,long offset){MaterialAllocationFailure injection(offset);return value.prepareDxfMLineLinetypes();}
    static bool mlineLinetypeProofAbsent(const dx_iface& value){
        if(!value.m_dxfMLineLinetypes.empty()||value.m_dxfMLineStyles.empty())return false;
        for(const auto& style:value.m_dxfMLineStyles)if(style.second.linetypesBound)return false;
        return true;
    }
    static bool mlineLinetypeProofBound(const dx_iface& value,std::uint32_t source){
        const auto row=value.m_dxfMLineLinetypes.find(source);
        if(row==value.m_dxfMLineLinetypes.end()||!value.m_dxfMLineLinetypesInspected
            ||!row->second.live||row->second.model.handle!=source||!row->second.emitted||row->second.table!=5u
            ||!row->second.origin||!row->second.origin->bodyMatched||!row->second.origin->stateComplete||!row->second.origin->originBound
            ||value.m_dxfMLineStyles.empty())return false;
        for(const auto& style:value.m_dxfMLineStyles)if(!style.second.linetypesBound)return false;
        return true;
    }
    static void limitMLineBlockSource(dx_iface& value);
    static bool mlineBlockSourceCaptureFailed(const dx_data& value);
    struct MLineBlockModelSwap {
        std::uint32_t block{0u};std::size_t dispatch{0u};std::shared_ptr<const DRW_MLine> original,anchor;
    };
    static MLineBlockModelSwap replaceMLineBlockModel(dx_data& value);
    static bool mlineBlockOwnerUnchanged(const dx_data& value,const MLineBlockModelSwap& saved);
    static bool restoreMLineBlockModel(dx_data& value,const MLineBlockModelSwap& saved);
    static bool chargeMLineComparisons(const std::vector<DRW_MLineElement>& elements,
            std::size_t passes,std::size_t& work,std::size_t limit){
        return dx_iface::chargeMlineComparisonWork(elements,passes,work,limit);
    }
    static bool prepareMLineStyleGeometry(dx_iface& value,bool binary){return value.prepareDxfMLineStyles(value.cData->sourceVersion,binary);}
    static bool mlineStylesReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view){
        const auto saved=value.m_dxfMLineStylesInspected;value.m_dxfMLineStylesInspected=false;
        const bool good=value.inspectDxfMLineStyles(view);value.m_dxfMLineStylesInspected=saved;return good;
    }
    static bool mlineAuthorityObjectsReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view){
        const auto styleInspected=value.m_dxfMLineStylesInspected;
        auto proofs=std::move(value.m_generatedRootOutputProofs);
        const auto bytes=value.m_generatedRootOutputBytes;
        const auto inspected=value.m_generatedRootOutputInspected;
        const auto finalized=value.m_generatedRootOutputFinalized;
        const auto published=value.m_generatedRootOutputPublished;
        value.m_dxfMLineStylesInspected=false;value.m_generatedRootOutputProofs.clear();
        value.m_generatedRootOutputBytes=0u;value.m_generatedRootOutputInspected=false;
        value.m_generatedRootOutputFinalized=false;value.m_generatedRootOutputPublished=false;
        const bool good=value.inspectDxfMLineStyles(view)&&value.inspectGeneratedRootOutput(view);
        value.m_dxfMLineStylesInspected=styleInspected;value.m_generatedRootOutputProofs=std::move(proofs);
        value.m_generatedRootOutputBytes=bytes;value.m_generatedRootOutputInspected=inspected;
        value.m_generatedRootOutputFinalized=finalized;value.m_generatedRootOutputPublished=published;
        return good;
    }
    static bool mlineConsumersReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view,std::string_view section){
        const auto saved=value.m_dxfMLineConsumerInspected;value.m_dxfMLineConsumerInspected=0u;
        const bool good=value.inspectDxfMLineConsumers(view,section);value.m_dxfMLineConsumerInspected=saved;return good;
    }
    static bool mlineLinetypesReplay(dx_iface& value,const dxfRW::DxfTablesWriteView& view){
        auto saved=value.m_dxfMLineLinetypes;const auto inspected=value.m_dxfMLineLinetypesInspected;
        value.m_dxfMLineLinetypesInspected=false;const bool good=value.inspectDxfMLineLinetypes(view);
        value.m_dxfMLineLinetypes=std::move(saved);value.m_dxfMLineLinetypesInspected=inspected;return good;
    }
    static std::function<void()> removeMLineLinetypeOrigin(dx_data& value,std::uint32_t handle);
    static std::function<void()> unqualifyMLineLinetypeOrigin(dx_data& value,std::uint32_t handle);
    static std::function<void()> removeMLineDictionaryOrigin(dx_data& value,std::uint32_t handle);
    static std::function<void()> removeMLineConsumerEvidence(dx_data& value,bool block);
    static bool mlineRetargetProofBound(const dx_iface& value,unsigned mask){
        if(!value.m_dxfMLineStylesInspected||value.m_dxfMLineConsumerInspected!=3u||value.m_dxfMLineConsumers.size()!=2u)return false;
        for(const auto handle:{0xDu,0xD2u}) {
            const auto style=value.m_dxfMLineStyles.find(handle);
            if(style==value.m_dxfMLineStyles.end()||!style->second.baseline||!style->second.dictionaryOrigin||!style->second.linetypesBound)return false;
        }
        for(unsigned i=0u;i<2u;++i) {
            const auto source=value.m_dxfMLineConsumers.find(i?0xD101u:0xD100u);
            if(source==value.m_dxfMLineConsumers.end()||!source->second.original||source->second.original->styleHandle!=0xDu
                ||source->second.model.styleHandle!=((mask&(1u<<i))?0xD2u:0xDu)||source->second.model.styleName!="OLD_ENTITY_NAME")return false;
        }
        return mlineLinetypeProofBound(value,0x101u)&&mlineLinetypeProofBound(value,0x102u);
    }
    static bool mlineStyleGeometryChanged(const dx_iface& value,std::uint32_t handle){
        const auto row=value.m_dxfMLineStyles.find(handle);return row!=value.m_dxfMLineStyles.end()&&row->second.geometryChanged;
    }
    static std::function<void()> misbindMLineLinetypeName(dx_data& value);
    static bool prepareScales(dx_iface& value,long offset,bool binary){MaterialAllocationFailure injection(offset);return value.prepareDxfScales(value.cData->sourceVersion,binary);}
    static bool scalesUnchanged(const dx_iface& value){return value.hasUnchangedDxfScales()&&value.m_dxfScalesInspected;}
    static bool scalesReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view){
        const auto saved=value.m_dxfScalesInspected;value.m_dxfScalesInspected=false;
        const bool good=value.inspectDxfScales(view);value.m_dxfScalesInspected=saved;return good;
    }
    static bool customVariableUnchanged(const dx_iface& value){return value.hasUnchangedDxfDictionaryVars();}
    static bool customVariableReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view){
        const auto saved=value.m_dxfDictionaryVarsInspected;value.m_dxfDictionaryVarsInspected=false;
        const bool good=value.inspectDxfDictionaryVars(view);value.m_dxfDictionaryVarsInspected=saved;return good;
    }
    static auto size(const dx_iface& value){return std::make_pair(value.m_dxfMaterialReferenceState.sources.size(),value.m_dxfMaterialReferenceState.bytes);}
    static void limit(dx_iface& value,std::size_t records,std::size_t bytes){value.m_dxfMaterialReferenceState.recordLimit=records;value.m_dxfMaterialReferenceState.byteLimit=bytes;}
    static bool finalize(const dx_iface& value){return value.finalizeDxfCommonReferences(347,value.m_dxfMaterialReferenceState);}
    static bool replay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view,std::string_view section){
        auto& state=value.m_dxfMaterialReferenceState;auto saved=state;
        state.sections&=~(section=="BLOCKS"?1u:2u);state.observedFields=0u;
        for(auto& row:state.sources)if(row.blocks==(section=="BLOCKS"))row.inspected=false;
        const bool result=value.inspectDxfCommonReferences(view,section,347,state);state=std::move(saved);return result;
    }
    static bool headerInactive(const dx_iface& value){return !value.m_dxfHeaderMaterialState.active&&!value.m_dxfHeaderMaterialState.inspected;}
    static bool headerReplay(dx_iface& value,const dxfRW::DxfHeaderWriteView& view){
        const auto saved=value.m_dxfHeaderMaterialState;value.m_dxfHeaderMaterialState.inspected=false;
        const bool good=value.inspectDxfHeaderMaterial(view)&&value.finalizeDxfHeaderMaterial();value.m_dxfHeaderMaterialState=saved;return good;
    }
    static auto layerSize(const dx_iface& value){return std::make_pair(value.m_dxfLayerMaterialState.rows.size(),value.m_dxfLayerMaterialState.bytes);}
    static void layerLimit(dx_iface& value,std::size_t records,std::size_t bytes){value.m_dxfLayerMaterialState.recordLimit=records;value.m_dxfLayerMaterialState.byteLimit=bytes;}
    static bool layerInactive(const dx_iface& value){return !value.m_dxfLayerMaterialState.active&&value.m_dxfLayerMaterialState.rows.empty()&&!value.m_dxfLayerMaterialState.inspected;}
    static bool layerReplay(dx_iface& value,const dxfRW::DxfObjectsWriteView& view,long fault=-1){
        auto& state=value.m_dxfLayerMaterialState;auto saved=state;state.inspected=false;
        for(auto& row:state.rows){row.named=false;row.inspected=false;row.emitted=0u;}
        for(auto& provider:state.providers)provider.second.observed=false;
        bool result=false;{MaterialAllocationFailure failure(fault);result=value.inspectDxfLayerMaterials(view)&&value.finalizeDxfLayerMaterials();}
        state=std::move(saved);return result;
    }
    static bool inactive(const dx_iface& value){return value.m_dxfMaterialReferenceState.sources.empty()&&value.m_dxfMaterialReferenceState.sections==0u&&value.dxfW
        &&value.dxfW->dxfWriteRecordHandleCount(value.dxfW->remapEntityHandle(0xE801u))==0u;}
};

class DxfDimensionDstyleTestAccess {
public:
    static bool matches(const DRW_Dimension& dimension,
                        bool canonicalOverrides) noexcept {
        if (canonicalOverrides) {
            return dimension.tolPlus == 0.25
                && dimension.tolMinus == 0.5
                && dimension.genTol && dimension.limGen
                && dimension.tolScale == 1.75
                && dimension.tolDecimals == 4
                && dimension.altTolDecimals == 3
                && dimension.textMove == 2
                && dimension.tolAlign == 1
                && dimension.tolZero == 5
                && dimension.altZero == 6
                && dimension.altTolZero == 7;
        }
        return dimension.tolPlus == 9.0
            && dimension.tolMinus == 8.0
            && dimension.tolScale == 7.0
            && !dimension.genTol && !dimension.limGen
            && dimension.tolDecimals == 1 && dimension.tolAlign == 0
            && dimension.tolZero == 0 && dimension.altTolDecimals == 0
            && dimension.altZero == 0 && dimension.altTolZero == 0
            && dimension.textMove == 0;
    }
};

