void testDxfTopLevelRecordFraming(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now()
        .time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-top-level-framing-" + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary DXF top-level framing directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    for (const bool binary : {false, true}) {
        const auto suffix = binary ? "binary" : "ascii";
        const auto minimalR12 = directory
            / (std::string("minimal-r12-no-tables-") + suffix + ".dxf");
        t.expect(writeMinimalR12EntitiesControl(minimalR12, binary),
                 "generated minimal R12 control without TABLES is complete");
        FixtureInterface minimalR12Interface;
        dx_data minimalR12Data;
        minimalR12Interface.attach(&minimalR12Data);
        dxfRW minimalR12Reader(minimalR12.string().c_str());
        t.expect(minimalR12Reader.read(&minimalR12Interface, false)
                     && minimalR12Data.mBlock->ent.size() == 1u,
                 "minimal R12 ENTITIES section remains readable without TABLES");

        const auto standard = directory / (std::string("standard-") + suffix + ".dxf");
        t.expect(writeTopLevelTableControl(standard, binary, false),
                 "generated standard TABLES section is complete");
        FixtureInterface standardInterface;
        dx_data standardData;
        standardInterface.attach(&standardData);
        dxfRW standardReader(standard.string().c_str());
        t.expect(standardReader.read(&standardInterface, false),
                 "standard TABLES section remains readable");
        t.expect(std::any_of(standardData.layers.begin(), standardData.layers.end(),
                             [](const DRW_Layer& layer) {
                                 return layer.name == "CAM_LAYER";
                             })
                     && standardData.mBlock->ent.size() == 1u,
                 "standard layer table and following LINE are both delivered");

        const auto orphan = directory / (std::string("orphan-") + suffix + ".dxf");
        t.expect(writeTopLevelTableControl(orphan, binary, true),
                 "generated out-of-section TABLE control is complete");
        FixtureInterface orphanInterface;
        dx_data orphanData;
        orphanInterface.attach(&orphanData);
        dxfRW orphanReader(orphan.string().c_str());
        t.expect(!orphanReader.read(&orphanInterface, false)
                     && orphanReader.getError() == DRW::BAD_READ_SECTION,
                 "out-of-section TABLE is rejected instead of silently skipped");
        t.expect(orphanData.mBlock->ent.empty(),
                 "no entity callbacks are delivered after invalid top-level TABLE framing");

        for (const auto marker : {std::pair<int, const char*>{2, "TABLES"},
                                  std::pair<int, const char*>{0, "ENDSEC"}}) {
            const bool sectionName = marker.first == 2;
            const auto malformed = directory
                / (std::string(sectionName ? "orphan-section-name-"
                                           : "orphan-endsec-")
                   + suffix + ".dxf");
            t.expect(writeTopLevelMarkerControl(
                         malformed, binary, marker.first, marker.second),
                     "generated detached top-level marker control is complete");
            FixtureInterface malformedInterface;
            dx_data malformedData;
            malformedInterface.attach(&malformedData);
            dxfRW malformedReader(malformed.string().c_str());
            t.expect(!malformedReader.read(&malformedInterface, false)
                         && malformedReader.getError() == DRW::BAD_READ_SECTION,
                     "detached section name and ENDSEC are rejected explicitly");
            t.expect(malformedData.mBlock->ent.empty(),
                     "no entity callbacks follow a detached top-level marker");
        }
    }
}

void testNodRootOrdering(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-nod-order-" + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary NOD ordering directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    for (const bool binary : {false, true}) {
        for (const bool rootOwnerPresent : {false, true}) {
            for (const bool extensionOwnerPresent : {false, true}) {
                const auto path = directory
                    / (std::string("conforming-") + (binary ? "binary" : "ascii")
                       + (rootOwnerPresent ? "-root-zero" : "-root-omitted")
                       + (extensionOwnerPresent ? "-extension-owned.dxf"
                                                 : "-extension-ownerless.dxf"));
                t.expect(writeNodOrderControl(path, binary, false,
                                              rootOwnerPresent,
                                              extensionOwnerPresent),
                         "generated conforming NOD-order control is complete");
                FixtureInterface interface_;
                dx_data data;
                interface_.cData = &data;
                interface_.currentBlock = data.mBlock;
                dxfRW reader(path.string().c_str());
                const bool imported = reader.read(&interface_, false);
                t.expect(imported,
                         "physically first NOD imports despite higher handle and owner spelling");
                const auto root = std::find_if(interface_.dictionaries.begin(),
                    interface_.dictionaries.end(), [](const DRW_Dictionary& value) {
                        return value.handle == 0xB0u;
                    });
                const auto extension = std::find_if(interface_.dictionaries.begin(),
                    interface_.dictionaries.end(), [](const DRW_Dictionary& value) {
                        return value.handle == 3u;
                    });
                const auto layoutDictionary = std::find_if(
                    interface_.dictionaries.begin(), interface_.dictionaries.end(),
                    [](const DRW_Dictionary& value) {
                        return value.handle == 0x500u;
                    });
                t.expect(interface_.dictionaries.size() == 3
                             && root != interface_.dictionaries.end()
                             && root->m_entries.size() == 2
                             && root->m_entries[0].m_name == "ACAD_LAYOUT"
                             && root->m_entries[0].m_handle == 0x500u
                             && root->m_entries[1].m_name == "TEST_ROOT"
                             && root->m_entries[1].m_handle == 0x300u
                             && extension != interface_.dictionaries.end()
                             && extension->m_entries.size() == 1
                             && extension->m_entries.front().m_name == "TEST_EXTENSION"
                             && extension->m_entries.front().m_handle == 0x400u
                             && layoutDictionary != interface_.dictionaries.end()
                             && layoutDictionary->parentHandle == 0xB0u
                             && layoutDictionary->m_entries.size() == 1
                             && layoutDictionary->m_entries.front().m_name
                                    == "NOD_ORDER_LAYOUT"
                             && layoutDictionary->m_entries.front().m_handle
                                    == 0x200u,
                         "root NOD, ACAD_LAYOUT dictionary and extension dictionary retain separate graph roles");
                const auto rawExtension = std::find_if(interface_.rawObjects.begin(),
                    interface_.rawObjects.end(), [](const DRW_RawDxfObject& value) {
                        return value.name == "DICTIONARY" && value.handle == 3u;
                    });
                t.expect(rawExtension != interface_.rawObjects.end()
                             && (extensionOwnerPresent
                                     ? rawExtension->parentHandle == 2u
                                     : rawExtension->parentHandle == 0u)
                             && std::count_if(interface_.rawObjects.begin(),
                                 interface_.rawObjects.end(),
                                 [](const DRW_RawDxfObject& value) {
                                     return value.name == "DICTIONARY"
                                         && value.handle == 0xB0u;
                                 }) == 0,
                         "only the positional root is suppressed from raw dictionary replay");
                t.expect(interface_.layouts.size() == 1
                             && interface_.layouts.front().handle == 0x200u
                             && interface_.layouts.front().name == "NOD_ORDER_LAYOUT"
                             && interface_.layouts.front().parentHandle == 0x500u
                             && interface_.layouts.front()
                                    .paperSpaceBlockRecordHandle.ref == 0x600u,
                         "named ACAD_LAYOUT dictionary entry targets a typed layout with distinct owner and block-record links");
            }
        }

        const auto malformed = directory
            / (binary ? "malformed-binary.dxf" : "malformed-ascii.dxf");
        t.expect(writeNodOrderControl(malformed, binary, true, true, true),
                 "generated owned-first malformed NOD control is complete");
        FixtureInterface malformedInterface;
        dx_data malformedData;
        malformedInterface.cData = &malformedData;
        malformedInterface.currentBlock = malformedData.mBlock;
        dxfRW malformedReader(malformed.string().c_str());
        t.expect(!malformedReader.read(&malformedInterface, false)
                     && malformedReader.getError() == DRW::BAD_READ_OBJECTS,
                 "owned first OBJECTS dictionary is rejected as a malformed NOD root");
        t.expect(malformedInterface.dictionaries.empty()
                     && malformedInterface.rawObjects.empty()
                     && malformedInterface.layouts.empty(),
                 "malformed root rejection occurs before object callbacks are published");

        const auto missingNod = directory
            / (binary ? "non-dictionary-first-binary.dxf"
                      : "non-dictionary-first-ascii.dxf");
        t.expect(writeNodOrderControl(missingNod, binary, false, false, true,
                                      true),
                 "generated no-root compatibility control is complete");
        FixtureInterface missingNodInterface;
        dx_data missingNodData;
        missingNodInterface.cData = &missingNodData;
        missingNodInterface.currentBlock = missingNodData.mBlock;
        dxfRW missingNodReader(missingNod.string().c_str());
        t.expect(missingNodReader.read(&missingNodInterface, false),
                 "legacy OBJECTS stream without a leading NOD remains readable");
        t.expect(std::count_if(missingNodInterface.rawObjects.begin(),
                              missingNodInterface.rawObjects.end(),
                              [](const DRW_RawDxfObject& value) {
                                  return value.name == "DICTIONARY"
                                      && value.handle == 0xB0u;
                              }) == 1,
                 "later ownerless dictionary is retained, not promoted as root");

        const auto output = directory
            / (binary ? "writer-root-first-binary.dxf"
                      : "writer-root-first-ascii.dxf");
        dx_data outputData;
        dx_iface writerInterface;
        t.expect(writerInterface.fileExport(output.string(), DRW::AC1027,
                                            binary, &outputData, false),
                 "empty drawing writer emits a valid OBJECTS section");
        FixtureInterface outputInterface;
        dx_data readbackData;
        t.expect(outputInterface.fileImport(output.string(), &readbackData,
                                            false),
                 "generated output with regenerated NOD re-imports");
        t.expect(outputInterface.dictionaries.size() >= 2
                     && outputInterface.dictionaries[0].handle == 0xCu
                     && outputInterface.dictionaries[0].m_entries.size() >= 1
                     && outputInterface.dictionaries[0].m_entries[0].m_name == "ACAD_GROUP"
                     && outputInterface.dictionaries[1].handle == 0xDu,
                 "writer places regenerated NOD before the reserved ACAD_GROUP dictionary");

        dx_data graphSource;
        graphSource.hasNamedObjectDictionary = true;
        graphSource.namedObjectDictionary.handle = 0xB0u;
        graphSource.namedObjectDictionary.m_entries = {
            {"NOD_CHILD", 0x3u}, {"NOD_DIRECT_XRECORD", 0x5u}};
        DRW_Dictionary child;
        child.handle = 0x3u;
        child.parentHandle = 0xB0u;
        child.m_entries.push_back({"NESTED_XRECORD", 0x4u});
        graphSource.dictionaries.push_back(child);
        DRW_XRecord nested;
        nested.handle = 0x4u;
        nested.parentHandle = 0x3u;
        nested.m_dataEntries.emplace_back(1, UTF8STRING("nested-nod-record"));
        graphSource.xRecords.push_back(nested);
        DRW_XRecord direct;
        direct.handle = 0x5u;
        direct.parentHandle = 0xB0u;
        direct.m_dataEntries.emplace_back(1, UTF8STRING("direct-nod-record"));
        graphSource.xRecords.push_back(direct);
        const auto graphOutput = directory
            / (binary ? "typed-nod-graph-binary.dxf"
                      : "typed-nod-graph-ascii.dxf");
        dx_iface graphWriter;
        const bool graphWritten = graphWriter.fileExport(
            graphOutput.string(), DRW::AC1027, binary, &graphSource,
            false, true);
        dx_data graphReadback;
        dx_iface graphReader;
        const bool graphRead = graphWritten
            && graphReader.fileImport(graphOutput.string(), &graphReadback,
                                      false);
        const auto childRootEntry = std::find_if(
            graphReadback.namedObjectDictionary.m_entries.begin(),
            graphReadback.namedObjectDictionary.m_entries.end(),
            [](const DRW_Dictionary::Entry& entry) {
                return entry.m_name == "NOD_CHILD";
            });
        const auto directRootEntry = std::find_if(
            graphReadback.namedObjectDictionary.m_entries.begin(),
            graphReadback.namedObjectDictionary.m_entries.end(),
            [](const DRW_Dictionary::Entry& entry) {
                return entry.m_name == "NOD_DIRECT_XRECORD";
            });
        const auto exportedChild = std::find_if(
            graphReadback.dictionaries.begin(), graphReadback.dictionaries.end(),
            [&childRootEntry, &graphReadback](const DRW_Dictionary& value) {
                return childRootEntry
                        != graphReadback.namedObjectDictionary.m_entries.end()
                    && value.handle == childRootEntry->m_handle;
            });
        const auto nestedRecord = std::find_if(
            graphReadback.xRecords.begin(), graphReadback.xRecords.end(),
            [&exportedChild, &graphReadback](const DRW_XRecord& value) {
                return exportedChild != graphReadback.dictionaries.end()
                    && value.parentHandle == exportedChild->handle;
            });
        const auto directRecord = std::find_if(
            graphReadback.xRecords.begin(), graphReadback.xRecords.end(),
            [&directRootEntry, &graphReadback](const DRW_XRecord& value) {
                return directRootEntry
                        != graphReadback.namedObjectDictionary.m_entries.end()
                    && value.handle == directRootEntry->m_handle;
            });
        t.expect(graphRead && graphReadback.hasNamedObjectDictionary
                     && graphReadback.namedObjectDictionary.handle == 0xCu
                     && childRootEntry
                         != graphReadback.namedObjectDictionary.m_entries.end()
                     && childRootEntry->m_handle != 0x3u
                     && exportedChild != graphReadback.dictionaries.end()
                     && exportedChild->parentHandle == 0xCu
                     && exportedChild->m_entries.size() == 1u
                     && exportedChild->m_entries.front().m_name
                         == "NESTED_XRECORD"
                     && nestedRecord != graphReadback.xRecords.end()
                     && nestedRecord->handle
                         == exportedChild->m_entries.front().m_handle
                     && nestedRecord->m_dataEntries.size() == 1u
                     && nestedRecord->m_dataEntries.front().content.s != nullptr
                     && *nestedRecord->m_dataEntries.front().content.s
                         == "nested-nod-record"
                     && directRootEntry
                         != graphReadback.namedObjectDictionary.m_entries.end()
                     && directRecord != graphReadback.xRecords.end()
                     && directRecord->parentHandle == 0xCu
                     && directRecord->handle != 0x5u
                     && directRecord->m_dataEntries.size() == 1u
                     && directRecord->m_dataEntries.front().content.s != nullptr
                     && *directRecord->m_dataEntries.front().content.s
                         == "direct-nod-record",
                 "strict export remaps a lower-handle NOD child and closes direct and nested XRECORDs");

        dx_data proxySource;
        proxySource.hasNamedObjectDictionary = true;
        proxySource.namedObjectDictionary.handle = 0xB0u;
        proxySource.namedObjectDictionary.m_entries.push_back(
            {"CUSTOM_PROXY", 0x730u});
        DRW_RawDxfObject rawProxy;
        rawProxy.name = "ACAD_PROXY_OBJECT";
        rawProxy.handle = 0x730u;
        rawProxy.parentHandle = 0xB0u;
        rawProxy.groups.emplace_back(5, UTF8STRING("730"));
        rawProxy.groups.emplace_back(330, UTF8STRING("B0"));
        rawProxy.groups.emplace_back(100, UTF8STRING("AcDbProxyObject"));
        rawProxy.groups.emplace_back(90, std::int32_t{499});
        rawProxy.groups.emplace_back(91, std::int32_t{500});
        rawProxy.groups.emplace_back(93, std::int32_t{0});
        rawProxy.groups.emplace_back(94, std::int32_t{0});
        rawProxy.groups.emplace_back(95, std::int32_t{0});
        rawProxy.groups.emplace_back(70, std::int32_t{0});
        proxySource.rawProxyObjects.push_back(rawProxy);
        DRW_Class proxyClass;
        proxyClass.recName = "LOCAL_CUSTOM_OBJECT";
        proxyClass.className = "LocalCustomObject";
        proxyClass.appName = "LocalTest";
        proxyClass.instanceCount = 1;
        proxyClass.wasaProxyFlag = 1;
        proxySource.dxfClasses.push_back(proxyClass);
        const auto strictProxyOutput = directory
            / (binary ? "strict-proxy-nod-binary.dxf"
                      : "strict-proxy-nod-ascii.dxf");
        {
            std::ofstream sentinel(strictProxyOutput,
                                   std::ios::binary | std::ios::trunc);
            sentinel << "untyped-root-sentinel";
        }
        dx_iface strictProxyWriter;
        const bool strictProxyWritten = strictProxyWriter.fileExport(
            strictProxyOutput.string(), DRW::AC1027, binary, &proxySource,
            false, true);
        std::ifstream strictProxyStream(strictProxyOutput, std::ios::binary);
        const std::string strictProxyBytes(
            (std::istreambuf_iterator<char>(strictProxyStream)),
            std::istreambuf_iterator<char>());
        t.expect(!strictProxyWritten
                     && strictProxyBytes == "untyped-root-sentinel",
                 "strict export rejects a NOD edge to a raw proxy before publication");

        const auto tolerantProxyOutput = directory
            / (binary ? "tolerant-proxy-nod-binary.dxf"
                      : "tolerant-proxy-nod-ascii.dxf");
        dx_iface tolerantProxyWriter;
        const bool tolerantProxyWritten = tolerantProxyWriter.fileExport(
            tolerantProxyOutput.string(), DRW::AC1027, binary, &proxySource,
            false);
        dx_data tolerantProxyReadback;
        dx_iface tolerantProxyReader;
        const bool tolerantProxyRead = tolerantProxyWritten
            && tolerantProxyReader.fileImport(tolerantProxyOutput.string(),
                                              &tolerantProxyReadback, false);
        t.expect(tolerantProxyRead
                     && std::none_of(
                         tolerantProxyReadback.namedObjectDictionary.m_entries.begin(),
                         tolerantProxyReadback.namedObjectDictionary.m_entries.end(),
                         [](const DRW_Dictionary::Entry& entry) {
                             return entry.m_name == "CUSTOM_PROXY";
                         })
                     && tolerantProxyReadback.rawProxyObjects.size() == 1u
                     && tolerantProxyReadback.rawProxyObjects.front().handle
                         == 0x730u
                     && tolerantProxyReadback.rawProxyObjects.front().parentHandle
                         == 0xCu,
                 "tolerant export omits an unsupported NOD edge but preserves its raw proxy object");

        proxySource.namedObjectDictionary.m_entries.clear();
        const auto unreferencedProxyOutput = directory
            / (binary ? "unreferenced-proxy-binary.dxf"
                      : "unreferenced-proxy-ascii.dxf");
        dx_iface unreferencedProxyWriter;
        const bool unreferencedProxyWritten = unreferencedProxyWriter.fileExport(
            unreferencedProxyOutput.string(), DRW::AC1027, binary,
            &proxySource, false, true);
        dx_data unreferencedProxyReadback;
        dx_iface unreferencedProxyReader;
        const bool unreferencedProxyRead = unreferencedProxyWritten
            && unreferencedProxyReader.fileImport(
                unreferencedProxyOutput.string(), &unreferencedProxyReadback,
                false);
        t.expect(unreferencedProxyRead
                     && std::none_of(
                         unreferencedProxyReadback.namedObjectDictionary.m_entries.begin(),
                         unreferencedProxyReadback.namedObjectDictionary.m_entries.end(),
                         [](const DRW_Dictionary::Entry& entry) {
                             return entry.m_name == "CUSTOM_PROXY";
                         })
                     && unreferencedProxyReadback.rawProxyObjects.size() == 1u
                     && unreferencedProxyReadback.rawProxyObjects.front().handle
                         == 0x730u,
                 "unreferenced raw proxy is emitted without creating a dangling NOD edge");
    }
}

void testVisualStyleRetention(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-visual-style-" + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary VisualStyle directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};
    const auto activeVport = [](const dx_data& data) -> const DRW_Vport* {
        const auto found = std::find_if(data.VPorts.begin(), data.VPorts.end(),
            [](const DRW_Vport& value) { return value.name == "*ACTIVE"; });
        return found == data.VPorts.end() ? nullptr : &*found;
    };

    for (const bool binary : {false, true}) {
      for (const char* styleHandle : {"701", "1C"}) {
        const std::uint32_t sourceStyleHandle = static_cast<std::uint32_t>(
            std::stoul(styleHandle, nullptr, 16));
        const auto path = directory
            / ((binary ? std::string("visual-style-binary")
                       : std::string("visual-style-ascii"))
               + (sourceStyleHandle == 0x1Cu ? "-collision.dxf" : ".dxf"));
        t.expect(writeVisualStyleRetentionControl(path, binary, true,
                                                  styleHandle),
                 "generated VisualStyle graph control is complete");

        dx_data data;
        dx_iface importer;
        importer.cData = &data;
        importer.currentBlock = data.mBlock;
        dxfRW reader(path.string().c_str());
        const bool imported = reader.read(&importer, false);
        const auto styleRoot = std::find_if(
            data.namedObjectDictionary.m_entries.begin(),
            data.namedObjectDictionary.m_entries.end(),
            [](const DRW_Dictionary::Entry& entry) {
                return entry.m_name == "ACAD_VISUALSTYLE";
            });
        const auto styleDictionary = std::find_if(
            data.dictionaries.begin(), data.dictionaries.end(),
            [](const DRW_Dictionary& dictionary) {
                return dictionary.handle == 0x700u;
            });
        const bool typedStyleRetained = data.visualStyles.size() == 1u
            && data.visualStyles.front().handle == sourceStyleHandle
            && data.visualStyles.front().parentHandle == 0x700u
            && data.visualStyles.front().desc == "CustomStyle"
            && data.visualStyles.front().type == 24
            && !data.visualStyles.front().m_bodyDecoded;
        const bool rawStyleRetained = data.rawVisualStyleObjects.size() == 1u
            && data.rawVisualStyleObjects.front().name == "VISUALSTYLE"
            && data.rawVisualStyleObjects.front().handle == sourceStyleHandle
            && data.rawVisualStyleObjects.front().parentHandle == 0x700u
            && data.rawVisualStyleObjects.front().groups.size() == 13u
            && data.rawVisualStyleObjects.front().rawValues.size() == 13u
            && data.rawVisualStyleObjects.front().groups.front().code() == 5
            && data.rawVisualStyleObjects.front().groups[1].code() == 330
            && data.rawVisualStyleObjects.front().groups[9].code() == 40
            && data.rawVisualStyleObjects.front().groups[9].d_val() == 0.75;
        const DRW_Viewport* sourceViewport = nullptr;
        if (data.mBlock != nullptr) {
            for (const DRW_Entity* entity : data.mBlock->ent) {
                sourceViewport = dynamic_cast<const DRW_Viewport*>(entity);
                if (sourceViewport != nullptr)
                    break;
            }
        }
        const DRW_Vport* sourceVport = activeVport(data);
        std::uint32_t interfereObjectStyle = 0;
        std::uint32_t interfereViewportStyle = 0;
        std::uint32_t dragStyle = 1;
        bool interfereObjectPresent = false;
        bool interfereViewportPresent = false;
        bool dragPresent = false;
        const bool headerReferencesRetained =
            data.headerC.getDxfVisualStyleReferenceHandle(
                "$INTERFEREOBJVS", interfereObjectStyle,
                interfereObjectPresent)
            && data.headerC.getDxfVisualStyleReferenceHandle(
                "$INTERFEREVPVS", interfereViewportStyle,
                interfereViewportPresent)
            && data.headerC.getDxfVisualStyleReferenceHandle(
                "$DRAGVS", dragStyle, dragPresent)
            && interfereObjectPresent && interfereViewportPresent
            && dragPresent && interfereObjectStyle == sourceStyleHandle
            && interfereViewportStyle == sourceStyleHandle
            && dragStyle == sourceStyleHandle;
        t.expect(imported && data.hasNamedObjectDictionary
                     && styleRoot
                         != data.namedObjectDictionary.m_entries.end()
                     && styleRoot->m_handle == 0x700u
                     && styleDictionary != data.dictionaries.end()
                     && styleDictionary->parentHandle == 0xB0u
                     && styleDictionary->m_entries.size() == 1u
                     && styleDictionary->m_entries.front().m_name
                         == "CustomStyle"
                     && styleDictionary->m_entries.front().m_handle
                         == sourceStyleHandle
                     && typedStyleRetained && rawStyleRetained
                     && sourceVport != nullptr
                     && sourceVport->visualStyleHandle == sourceStyleHandle
                     && sourceViewport != nullptr
                     && sourceViewport->shadePlotMode == 4
                     && sourceViewport->shadePlotHandle == sourceStyleHandle
                     && headerReferencesRetained,
                 binary
                     ? "binary input retains rooted VisualStyle plus VPORT and VIEWPORT edges"
                     : "ASCII input retains rooted VisualStyle plus VPORT and VIEWPORT edges");

        const auto exportedPath = directory
            / (binary ? "visual-style-export-binary.dxf"
                      : "visual-style-export-ascii.dxf");
        dx_data exportData;
        dx_iface graphAdapter;
        const bool graphImported = graphAdapter.fileImport(
            path.string(), &exportData, false);
        const bool graphExported = graphImported && graphAdapter.fileExport(
            exportedPath.string(), DRW::AC1027, binary, &exportData, false);
        dx_data verifiedData;
        dx_iface verifier;
        const bool graphVerified = graphExported && verifier.fileImport(
            exportedPath.string(), &verifiedData, false);
        const DRW_Viewport* exportedViewport = nullptr;
        if (graphVerified && verifiedData.mBlock != nullptr) {
            for (const DRW_Entity* entity : verifiedData.mBlock->ent) {
                exportedViewport = dynamic_cast<const DRW_Viewport*>(entity);
                if (exportedViewport != nullptr)
                    break;
            }
        }
        const DRW_Vport* exportedVport = activeVport(verifiedData);
        const auto exportedStyleRoot = std::find_if(
            verifiedData.namedObjectDictionary.m_entries.begin(),
            verifiedData.namedObjectDictionary.m_entries.end(),
            [](const DRW_Dictionary::Entry& entry) {
                return entry.m_name == "ACAD_VISUALSTYLE";
            });
        std::uint32_t emittedInterfereObjectStyle = 0;
        std::uint32_t emittedInterfereViewportStyle = 0;
        std::uint32_t emittedDragStyle = 1;
        bool emittedInterfereObjectPresent = false;
        bool emittedInterfereViewportPresent = false;
        bool emittedDragPresent = false;
        const bool emittedHeaderTargets = graphVerified
            && !verifiedData.visualStyles.empty()
            && verifiedData.headerC.getDxfVisualStyleReferenceHandle(
                "$INTERFEREOBJVS", emittedInterfereObjectStyle,
                emittedInterfereObjectPresent)
            && verifiedData.headerC.getDxfVisualStyleReferenceHandle(
                "$INTERFEREVPVS", emittedInterfereViewportStyle,
                emittedInterfereViewportPresent)
            && verifiedData.headerC.getDxfVisualStyleReferenceHandle(
                "$DRAGVS", emittedDragStyle, emittedDragPresent)
            && emittedInterfereObjectPresent
            && emittedInterfereViewportPresent && emittedDragPresent
            && emittedInterfereObjectStyle
                == verifiedData.visualStyles.front().handle
            && emittedInterfereViewportStyle
                == verifiedData.visualStyles.front().handle
            && emittedDragStyle == verifiedData.visualStyles.front().handle
            && (sourceStyleHandle != 0x1Cu
                || emittedInterfereObjectStyle != sourceStyleHandle);
        const bool emittedStyleTarget = graphVerified
            && emittedHeaderTargets
            && verifiedData.visualStyles.size() == 1u
            && exportedVport != nullptr
            && exportedVport->visualStyleHandle
                == verifiedData.visualStyles.front().handle
            && (sourceStyleHandle != 0x1Cu
                || exportedVport->visualStyleHandle != sourceStyleHandle)
            && exportedViewport != nullptr
            && exportedViewport->shadePlotMode == 4
            && exportedViewport->shadePlotHandle
                == verifiedData.visualStyles.front().handle
            && exportedStyleRoot
                != verifiedData.namedObjectDictionary.m_entries.end()
            && std::any_of(verifiedData.dictionaries.begin(),
                verifiedData.dictionaries.end(),
                [&exportedStyleRoot, &verifiedData](
                    const DRW_Dictionary& dictionary) {
                    return dictionary.handle == exportedStyleRoot->m_handle
                        && dictionary.m_entries.size() == 1u
                        && dictionary.m_entries.front().m_handle
                            == verifiedData.visualStyles.front().handle;
                });
        t.expect(emittedStyleTarget,
                 binary
                     ? "binary adapter round-trip remaps VPORT code-348 and VIEWPORT shade edge to rooted VisualStyle"
                     : "ASCII adapter round-trip remaps VPORT code-348 and VIEWPORT shade edge to rooted VisualStyle");

        const auto noStylePath = directory
            / (binary ? "no-visual-style-binary.dxf"
                      : "no-visual-style-ascii.dxf");
        t.expect(writeVisualStyleRetentionControl(noStylePath, binary, false),
                 "generated no-VisualStyle control is complete");
        dx_data noStyleData;
        dx_iface noStyleImporter;
        noStyleImporter.cData = &noStyleData;
        noStyleImporter.currentBlock = noStyleData.mBlock;
        dxfRW noStyleReader(noStylePath.string().c_str());
        const bool noStyleRead = noStyleReader.read(&noStyleImporter, false);
        std::uint32_t noStyleDragHandle = 1;
        bool noStyleDragPresent = false;
        const bool noStyleNullRetained =
            noStyleData.headerC.getDxfVisualStyleReferenceHandle(
                "$DRAGVS", noStyleDragHandle, noStyleDragPresent)
            && noStyleDragPresent && noStyleDragHandle == 0;
        t.expect(noStyleRead
                     && noStyleData.visualStyles.empty()
                     && noStyleData.rawVisualStyleObjects.empty()
                     && noStyleNullRetained,
                 binary
                     ? "binary explicit-null HEADER reference is retained without style callbacks"
                     : "ASCII explicit-null HEADER reference is retained without style callbacks");
        const auto noStyleOutputPath = directory
            / (binary ? "no-visual-style-output-binary.dxf"
                      : "no-visual-style-output-ascii.dxf");
        dx_data noStyleRoundTripData;
        dx_iface noStyleRoundTripAdapter;
        const bool noStyleExported = noStyleRoundTripAdapter.fileImport(
            noStylePath.string(), &noStyleRoundTripData, false)
            && noStyleRoundTripAdapter.fileExport(noStyleOutputPath.string(),
                DRW::AC1027, binary, &noStyleRoundTripData, false);
        dx_data noStyleVerifiedData;
        dx_iface noStyleVerifier;
        const bool noStyleRoundTrip = noStyleExported
            && noStyleVerifier.fileImport(noStyleOutputPath.string(),
                                           &noStyleVerifiedData, false);
        std::uint32_t verifiedNullDragHandle = 1;
        bool verifiedNullDragPresent = false;
        t.expect(noStyleRoundTrip
                     && noStyleVerifiedData.headerC
                         .getDxfVisualStyleReferenceHandle(
                             "$DRAGVS", verifiedNullDragHandle,
                             verifiedNullDragPresent)
                     && verifiedNullDragPresent
                     && verifiedNullDragHandle == 0,
                 binary
                     ? "binary export preserves an explicit-null HEADER VisualStyle reference"
                     : "ASCII export preserves an explicit-null HEADER VisualStyle reference");
        const auto noStyleVport = std::find_if(
            noStyleRoundTripData.VPorts.begin(), noStyleRoundTripData.VPorts.end(),
            [](const DRW_Vport& value) { return value.name == "*ACTIVE"; });
        t.expect(noStyleVport != noStyleRoundTripData.VPorts.end()
                     && noStyleVport->visualStyleHandle == 0,
                 binary
                     ? "binary no-style VPORT has no VisualStyle edge"
                     : "ASCII no-style VPORT has no VisualStyle edge");
        if (noStyleVport != noStyleRoundTripData.VPorts.end()) {
            const auto invalidPath = directory
                / (binary ? "vport-dangling-binary.dxf"
                          : "vport-dangling-ascii.dxf");
            {
                std::ofstream sentinel(invalidPath,
                    std::ios::binary | std::ios::trunc);
                sentinel << "vport-visual-style-sentinel";
            }
            noStyleVport->visualStyleHandle = 0x777u;
            const bool rejected = !noStyleRoundTripAdapter.fileExport(
                invalidPath.string(), DRW::AC1027, binary,
                &noStyleRoundTripData, false);
            std::ifstream invalidOutput(invalidPath, std::ios::binary);
            const std::string invalidBytes(
                (std::istreambuf_iterator<char>(invalidOutput)),
                std::istreambuf_iterator<char>());
            noStyleVport->visualStyleHandle = 0;
            const bool retry = noStyleRoundTripAdapter.fileExport(
                invalidPath.string(), DRW::AC1027, binary,
                &noStyleRoundTripData, false);
            t.expect(rejected && invalidBytes == "vport-visual-style-sentinel"
                         && retry,
                     binary
                         ? "binary export rejects dangling VPORT VisualStyle atomically and retries"
                         : "ASCII export rejects dangling VPORT VisualStyle atomically and retries");
        }
      }
    }

    for (const bool binary : {false, true}) {
        const auto checkRejectedExport = [&](const char* name,
                                             DRW::Version targetVersion,
                                             const char* value) {
            const auto outputPath = directory / name;
            {
                std::ofstream sentinel(outputPath,
                    std::ios::binary | std::ios::trunc);
                sentinel << "header-visual-style-sentinel";
            }
            dx_data data;
            data.headerC.addStr("$DRAGVS", value, 349);
            dx_iface adapter;
            const bool exported = adapter.fileExport(
                outputPath.string(), targetVersion, binary, &data, false);
            std::ifstream output(outputPath, std::ios::binary);
            const std::string bytes((std::istreambuf_iterator<char>(output)),
                                    std::istreambuf_iterator<char>());
            return !exported && bytes == "header-visual-style-sentinel";
        };
        t.expect(checkRejectedExport(
                     binary ? "header-dangling-binary.dxf"
                            : "header-dangling-ascii.dxf",
                     DRW::AC1027, "123456"),
                 binary
                     ? "binary export rejects an unrooted HEADER VisualStyle target atomically"
                     : "ASCII export rejects an unrooted HEADER VisualStyle target atomically");
        t.expect(checkRejectedExport(
                     binary ? "header-downlevel-binary.dxf"
                            : "header-downlevel-ascii.dxf",
                     DRW::AC1018, "0"),
                 binary
                     ? "binary export rejects a present HEADER VisualStyle variable for AC1018 atomically"
                     : "ASCII export rejects a present HEADER VisualStyle variable for AC1018 atomically");
    }

    const auto wrongClassPath = directory / "header-wrong-class-input.dxf";
    const auto wrongClassOutput = directory / "header-wrong-class-output.dxf";
    t.expect(writeVisualStyleRetentionControl(wrongClassPath, false),
             "generated wrong-class HEADER reference source is complete");
    dx_data wrongClassData;
    dx_iface wrongClassAdapter;
    const bool wrongClassImported = wrongClassAdapter.fileImport(
        wrongClassPath.string(), &wrongClassData, false);
    wrongClassData.headerC.addStr("$DRAGVS", "700", 349);
    {
        std::ofstream sentinel(wrongClassOutput,
            std::ios::binary | std::ios::trunc);
        sentinel << "header-wrong-class-sentinel";
    }
    const bool wrongClassExported = wrongClassImported
        && wrongClassAdapter.fileExport(wrongClassOutput.string(),
            DRW::AC1027, false, &wrongClassData, false);
    std::ifstream wrongClassOutputFile(wrongClassOutput, std::ios::binary);
    const std::string wrongClassBytes(
        (std::istreambuf_iterator<char>(wrongClassOutputFile)),
        std::istreambuf_iterator<char>());
    t.expect(wrongClassImported && !wrongClassExported
                 && wrongClassBytes == "header-wrong-class-sentinel",
             "export rejects HEADER VisualStyle target of dictionary class atomically");
}

void testViewLiveSectionFailClosed(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-view-live-section-"
           + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary VIEW LiveSection directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    class DirectViewWriter final : public dx_iface {
    public:
        void writeViews() override {
            DRW_View view;
            view.name = "DIRECT_LIVE_SECTION_VIEW";
            view.m_liveSectionHandle = 0x777u;
            lowLevelWrite = dxfW->writeView(&view);
        }
        bool lowLevelWrite {true};
    };

    for (const bool binary : {false, true}) {
        const auto input = directory
            / (binary ? "live-section-binary.dxf" : "live-section-ascii.dxf");
        t.expect(writeViewReferenceControl(
                     input, binary, 334, "LIVE_SECTION_VIEW"),
                 "generated VIEW code-334 control is complete");
        dx_data data;
        dx_iface adapter;
        const bool imported = adapter.fileImport(input.string(), &data, false);
        const auto sourceView = std::find_if(data.views.begin(), data.views.end(),
            [](const DRW_View& view) {
                return view.name == "LIVE_SECTION_VIEW";
            });
        t.expect(imported && sourceView != data.views.end()
                     && sourceView->m_liveSectionHandle == 0x777u,
                 binary
                     ? "binary parser retains VIEW LiveSection code-334 handle"
                     : "ASCII parser retains VIEW LiveSection code-334 handle");
        if (!imported || sourceView == data.views.end())
            continue;

        const auto rejectedPath = directory
            / (binary ? "live-section-rejected-binary.dxf"
                      : "live-section-rejected-ascii.dxf");
        const std::string sentinel = "live-section destination sentinel";
        {
            std::ofstream output(rejectedPath,
                std::ios::binary | std::ios::trunc);
            output << sentinel;
        }
        const bool rejected = !adapter.fileExport(
            rejectedPath.string(), DRW::AC1027, binary, &data, false);
        std::ifstream rejectedOutput(rejectedPath, std::ios::binary);
        const std::string rejectedBytes(
            (std::istreambuf_iterator<char>(rejectedOutput)), {});
        t.expect(rejected && rejectedBytes == sentinel,
                 binary
                     ? "binary adapter refuses unqualified VIEW code-334 edge atomically"
                     : "ASCII adapter refuses unqualified VIEW code-334 edge atomically");

        sourceView->m_liveSectionHandle = 0;
        const auto correctedPath = directory
            / (binary ? "live-section-corrected-binary.dxf"
                      : "live-section-corrected-ascii.dxf");
        const bool corrected = adapter.fileExport(
            correctedPath.string(), DRW::AC1027, binary, &data, false);
        bool correctedViewWire = false;
        bool emittedLiveSection = false;
        bool emittedOrthoWithoutUcs = false;
        bool sawNoUcsFlag = false;
        if (corrected) {
            std::ifstream output(correctedPath, std::ios::binary);
            if (binary)
                output.seekg(22);
            std::unique_ptr<dxfReader> reader = binary
                ? std::unique_ptr<dxfReader>(new dxfReaderBinary(&output))
                : std::unique_ptr<dxfReader>(new dxfReaderAscii(&output));
            bool inViewRecord = false;
            bool sawViewRecord = false;
            int code = 0;
            while (reader->readRec(&code)) {
                if (code == 0) {
                    inViewRecord = reader->getString() == "VIEW";
                    sawViewRecord = sawViewRecord || inViewRecord;
                    continue;
                }
                if (!inViewRecord)
                    continue;
                if (code == 334)
                    emittedLiveSection = true;
                else if (code == 72)
                    sawNoUcsFlag = reader->getInt32() == 0;
                else if (code == 79)
                    emittedOrthoWithoutUcs = true;
            }
            correctedViewWire = sawViewRecord && sawNoUcsFlag
                && !emittedLiveSection && !emittedOrthoWithoutUcs;
        }
        dx_data verifiedData;
        dx_iface verifier;
        const bool verified = corrected && verifier.fileImport(
            correctedPath.string(), &verifiedData, false);
        const auto verifiedView = std::find_if(
            verifiedData.views.begin(), verifiedData.views.end(),
            [](const DRW_View& view) {
                return view.name == "LIVE_SECTION_VIEW";
            });
        t.expect(verified && verifiedView != verifiedData.views.end()
                     && verifiedView->m_liveSectionHandle == 0
                     && !verifiedView->hasUCS && correctedViewWire,
                 binary
                     ? "binary same-adapter retry succeeds after LiveSection is cleared and emits no inapplicable UCS group 79"
                     : "ASCII same-adapter retry succeeds after LiveSection is cleared and emits no inapplicable UCS group 79");

        const auto lowLevelPath = directory
            / (binary ? "live-section-low-level-binary.dxf"
                      : "live-section-low-level-ascii.dxf");
        {
            std::ofstream output(lowLevelPath,
                std::ios::binary | std::ios::trunc);
            output << sentinel;
        }
        dx_data emptyData;
        DirectViewWriter directWriter;
        const bool lowLevelExport = directWriter.fileExport(
            lowLevelPath.string(), DRW::AC1027, binary, &emptyData, false);
        std::ifstream lowLevelOutput(lowLevelPath, std::ios::binary);
        const std::string lowLevelBytes(
            (std::istreambuf_iterator<char>(lowLevelOutput)), {});
        t.expect(!lowLevelExport && !directWriter.lowLevelWrite
                     && lowLevelBytes == sentinel,
                 binary
                     ? "binary direct VIEW writer refuses code-334 atomically"
                     : "ASCII direct VIEW writer refuses code-334 atomically");
    }
}

bool viewRecordHasCode(const std::filesystem::path& path, bool binary,
                      const std::string& viewName, int targetCode) {
    std::ifstream input(path, std::ios::binary);
    if (!input)
        return false;
    if (binary)
        input.seekg(22);
    std::unique_ptr<dxfReader> reader = binary
        ? std::unique_ptr<dxfReader>(new dxfReaderBinary(&input))
        : std::unique_ptr<dxfReader>(new dxfReaderAscii(&input));
    bool inView = false;
    bool matchingView = false;
    int code = 0;
    while (reader->readRec(&code)) {
        if (code == 0) {
            inView = reader->getString() == "VIEW";
            matchingView = false;
            continue;
        }
        if (!inView)
            continue;
        if (code == 2) {
            matchingView = reader->getString() == viewName;
            continue;
        }
        if (matchingView && code == targetCode)
            return true;
    }
    return false;
}

void testViewBackgroundAndSunFailClosed(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-view-object-refs-" + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary VIEW background/SUN directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    struct ReferenceCase {
        int code;
        const char* viewName;
        const char* label;
    };
    const ReferenceCase cases[] = {
        {332, "BACKGROUND_VIEW", "Background"},
        {361, "SUN_VIEW", "SUN"}
    };
    const auto referenceValue = [](DRW_View& view, int code) -> std::uint32_t& {
        return code == 332 ? view.m_backgroundHandle : view.m_sunHandle;
    };

    class DirectViewWriter final : public dx_iface {
    public:
        explicit DirectViewWriter(int referenceCode)
            : referenceCode(referenceCode) {}
        void writeViews() override {
            DRW_View view;
            view.name = "DIRECT_OBJECT_REFERENCE_VIEW";
            if (referenceCode == 332)
                view.m_backgroundHandle = 0x777u;
            else
                view.m_sunHandle = 0x777u;
            lowLevelWrite = dxfW->writeView(&view);
        }
        int referenceCode;
        bool lowLevelWrite {true};
    };

    for (const bool binary : {false, true}) {
        for (const ReferenceCase& item : cases) {
            const auto input = directory
                / (std::string(item.viewName)
                   + (binary ? "-binary.dxf" : "-ascii.dxf"));
            t.expect(writeViewReferenceControl(
                         input, binary, item.code, item.viewName),
                     (std::string("generated VIEW ") + item.label
                         + " control is complete").c_str());
            dx_data data;
            dx_iface adapter;
            const bool imported = adapter.fileImport(input.string(), &data, false);
            const auto sourceView = std::find_if(data.views.begin(), data.views.end(),
                [&item](const DRW_View& view) {
                    return view.name == item.viewName;
                });
            t.expect(imported && sourceView != data.views.end()
                         && referenceValue(*sourceView, item.code) == 0x777u,
                     (std::string(binary ? "binary " : "ASCII ")
                         + "parser retains VIEW " + item.label + " reference").c_str());
            if (!imported || sourceView == data.views.end())
                continue;

            const auto rejectedPath = directory
                / (std::string(item.viewName)
                   + (binary ? "-refused-binary.dxf" : "-refused-ascii.dxf"));
            const std::string sentinel = "VIEW object-reference sentinel";
            {
                std::ofstream output(rejectedPath,
                    std::ios::binary | std::ios::trunc);
                output << sentinel;
            }
            const bool rejected = !adapter.fileExport(
                rejectedPath.string(), DRW::AC1027, binary, &data, false);
            std::ifstream rejectedOutput(rejectedPath, std::ios::binary);
            const std::string rejectedBytes(
                (std::istreambuf_iterator<char>(rejectedOutput)), {});
            t.expect(rejected && rejectedBytes == sentinel,
                     (std::string(binary ? "binary " : "ASCII ")
                         + "adapter refuses unqualified VIEW " + item.label
                         + " graph atomically").c_str());

            referenceValue(*sourceView, item.code) = 0;
            const auto correctedPath = directory
                / (std::string(item.viewName)
                   + (binary ? "-corrected-binary.dxf"
                             : "-corrected-ascii.dxf"));
            const bool corrected = adapter.fileExport(
                correctedPath.string(), DRW::AC1027, binary, &data, false);
            dx_data verifiedData;
            dx_iface verifier;
            const bool verified = corrected && verifier.fileImport(
                correctedPath.string(), &verifiedData, false);
            const auto verifiedView = std::find_if(
                verifiedData.views.begin(), verifiedData.views.end(),
                [&item](const DRW_View& view) {
                    return view.name == item.viewName;
                });
            t.expect(verified && verifiedView != verifiedData.views.end()
                         && referenceValue(*verifiedView, item.code) == 0
                         && !viewRecordHasCode(correctedPath, binary,
                                               item.viewName, item.code),
                     (std::string(binary ? "binary " : "ASCII ")
                         + "same-adapter retry removes unsupported VIEW "
                         + item.label + " edge").c_str());

            const auto directPath = directory
                / (std::string(item.viewName)
                   + (binary ? "-direct-binary.dxf" : "-direct-ascii.dxf"));
            {
                std::ofstream output(directPath,
                    std::ios::binary | std::ios::trunc);
                output << sentinel;
            }
            dx_data emptyData;
            DirectViewWriter directWriter(item.code);
            const bool directExport = directWriter.fileExport(
                directPath.string(), DRW::AC1027, binary, &emptyData, false);
            std::ifstream directOutput(directPath, std::ios::binary);
            const std::string directBytes(
                (std::istreambuf_iterator<char>(directOutput)), {});
            t.expect(!directExport && !directWriter.lowLevelWrite
                         && directBytes == sentinel,
                     (std::string(binary ? "binary " : "ASCII ")
                         + "direct VIEW writer refuses unqualified "
                         + item.label + " edge atomically").c_str());
        }
    }
}

void testVisualStyleTypeScope(TestContext& t) {
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-style-type-" + std::to_string(
            std::chrono::steady_clock::now().time_since_epoch().count()));
    if (!std::filesystem::create_directory(directory)) {
        t.expect(false, "style-type test owns a fresh scratch directory");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() { std::error_code error; std::filesystem::remove_all(path, error); }
    } cleanup{directory};
    const auto basic = [] {
        return std::vector<DRW_Variant>{
            {100, UTF8STRING("AcDbVisualStyle")}, {2, UTF8STRING("ScopedStyle")},
            {70, 8}, {177, 3}, {291, 0}};
    };
    struct Case {
        const char* name;
        const char* version;
        std::vector<DRW_Variant> body;
    };
    std::vector<Case> cases;
    auto two = basic();
    two.insert(two.end(), {{70, 2}, {62, 7}, {420, 0}, {176, -1},
                           {90, 123456}, {176, 2}});
    cases.push_back({"two", "AC1032", two});
    auto flag = two;
    flag[4] = DRW_Variant(291, 1);
    cases.push_back({"internal-flag", "AC1032", flag});
    auto many = basic();
    many.emplace_back(70, 58);
    for (int i = 0; i < 58; ++i) {
        many.emplace_back(90, i);
        many.emplace_back(176, i % 4);
    }
    cases.push_back({"count58", "AC1032", many});
    auto wrong = two;
    wrong[5] = DRW_Variant(70, 3);
    cases.push_back({"wrong-count", "AC1032", wrong});
    auto missing = two;
    missing.pop_back();
    cases.push_back({"missing-companion", "AC1032", missing});
    auto legacy = basic();
    legacy.insert(legacy.end(), {{90, 123456}, {176, 1}});
    cases.push_back({"older-profile", "AC1024", legacy});
    cases.push_back({"markerless", "AC1024", {{4, UTF8STRING("ScopedStyle")}, {70, 8}}});
    auto subclass = two;
    subclass.insert(subclass.begin(), {{100, UTF8STRING("AcDbObject")},
        {70, 99}, {2, UTF8STRING("ForeignDescription")}, {291, 1}});
    subclass.insert(subclass.end(), {{100, UTF8STRING("ForeignSubclass")},
        {70, 101}, {2, UTF8STRING("ForeignTail")},
        {100, UTF8STRING("AcDbVisualStyle")}, {70, 59},
        {4, UTF8STRING("RepeatedSubclassTail")}});
    cases.push_back({"subclass-scopes", "AC1032", subclass});

    const auto findStyle = [](const auto& styles, const char* desc) {
        return std::find_if(styles.begin(), styles.end(), [desc](const auto& value) {
            return value.desc == desc;
        });
    };
    const auto bodyMatches = [](const DRW_RawDxfObject& left, const DRW_RawDxfObject& right) {
        if (left.groups.size() != right.groups.size()
            || left.rawValues.size() != left.groups.size()
            || right.rawValues.size() != right.groups.size()) return false;
        for (std::size_t i = 0; i < left.groups.size(); ++i) {
            const auto& a = left.groups[i]; const auto& b = right.groups[i];
            if (a.code() != b.code() || a.type() != b.type()) return false;
            if (a.code() == 5 || a.code() == 330) continue; // Regenerated identities.
            if (a.type() == DRW_Variant::STRING) {
                if (std::string(a.c_str()) != b.c_str()
                    || left.rawValues[i] != right.rawValues[i]) return false;
            } else if (a.type() == DRW_Variant::INTEGER) {
                if (a.i_val() != b.i_val()) return false;
            } else return false;
        }
        return true;
    };
    for (const bool binary : {false, true}) {
        for (const auto& row : cases) {
            const auto path = directory / (std::string(row.name) + (binary ? "-b.dxf" : "-a.dxf"));
            t.expect(writeVisualStyleScopedControl(path, binary, row.version, row.body),
                     "authored scoped style record and independent suffix are complete");
            dx_data data;
            dx_iface importer;
            const bool read = importer.fileImport(path.string(), &data, false);
            const auto main = findStyle(data.visualStyles, "ScopedStyle");
            const auto following = findStyle(data.visualStyles, "FollowingStyle");
            const auto raw = std::find_if(data.rawVisualStyleObjects.begin(), data.rawVisualStyleObjects.end(),
                [](const auto& value) { return value.handle == 0x701u; });
            t.expect(read && data.visualStyles.size() == 2u
                         && main != data.visualStyles.end() && main->type == 8
                         && !main->m_bodyDecoded && main->m_body.m_encoding.companionCount == 0u
                         && following != data.visualStyles.end() && following->type == 12
                         && data.xRecords.size() == 1u
                         && !data.xRecords.front().m_values.empty()
                         && std::string(data.xRecords.front().m_values.front().c_str()) == "SCOPED_STYLE_SUFFIX",
                     "style type is basic70, not tail count; new object and suffix remain independent");
            if (!read || raw == data.rawVisualStyleObjects.end()) continue;
            t.expect(raw->groups.size() == row.body.size() + 2u,
                     "type guard does not discard any raw style group");
            const auto original = *raw;
            const auto output = directory / (std::string(row.name) + (binary ? "-out-b.dxf" : "-out-a.dxf"));
            dx_iface converter;
            const auto target = std::string(row.version) == "AC1024" ? DRW::AC1024 : DRW::AC1032;
            for (int pass = 0; pass < 2; ++pass) {
                t.expect(converter.fileExport(output.string(), target, binary, &data, false, true),
                         "scoped raw style can be converted without claiming property validation");
                dx_data reopened;
                dx_iface input;
                const bool reopenedOk = input.fileImport(output.string(), &reopened, false);
                const auto style = findStyle(reopened.visualStyles, "ScopedStyle");
                const auto nextStyle = findStyle(reopened.visualStyles, "FollowingStyle");
                const auto retained = std::find_if(reopened.rawVisualStyleObjects.begin(), reopened.rawVisualStyleObjects.end(),
                    [&original, &bodyMatches](const auto& value) { return bodyMatches(original, value); });
                t.expect(reopenedOk && style != reopened.visualStyles.end() && style->type == 8
                             && retained != reopened.rawVisualStyleObjects.end()
                             && reopened.visualStyles.size() == 2u && reopened.xRecords.size() == 1u
                             && nextStyle != reopened.visualStyles.end() && nextStyle->type == 12
                             && !reopened.xRecords.front().m_values.empty()
                             && std::string(reopened.xRecords.front().m_values.front().c_str()) == "SCOPED_STYLE_SUFFIX"
                             && main != data.visualStyles.end() && main->handle == 0x701u
                             && bodyMatches(original, *raw),
                         "ASCII/binary repeat conversion retains typed type, exact raw body and caller identities");
            }
        }
        // Failed object input must not publish partial typed/raw state. Reuse
        // the same facade after replacing only this locally authored input.
        const auto path = directory / (binary ? "retry-b.dxf" : "retry-a.dxf");
        t.expect(writeVisualStyleScopedControl(path, binary, "AC1032", many, false),
                 "truncated control omits the object boundary");
        dx_data incomplete;
        dx_iface sink;
        sink.cData = &incomplete; sink.currentBlock = incomplete.mBlock;
        dxfRW codec(path.string().c_str());
        t.expect(!codec.read(&sink, false) && incomplete.visualStyles.empty()
                     && incomplete.rawVisualStyleObjects.empty(),
                 "truncated style publishes neither partial typed data nor its raw companion");
        t.expect(writeVisualStyleScopedControl(path, binary, "AC1032", many),
                 "same input identity receives the corrected complete control");
        dx_data corrected;
        sink.cData = &corrected; sink.currentBlock = corrected.mBlock;
        t.expect(codec.read(&sink, false) && corrected.visualStyles.size() == 2u
                     && corrected.visualStyles.front().type == 8,
                 "same reader facade retries with fresh scoped style state");
    }

    class Parser final : public DRW_VisualStyle { public: using DRW_VisualStyle::parseCode; };
    const auto parse = [&t](Parser& target, const char* pairs) {
        std::istringstream bytes(pairs);
        std::unique_ptr<dxfReader> reader = std::make_unique<dxfReaderAscii>(&bytes);
        int code = 0;
        while (reader->readRec(&code))
            t.expect(target.parseCode(code, reader), "direct style parser accepts controlled group");
    };
    Parser source;
    parse(source, "100\nAcDbVisualStyle\n2\nOriginal\n70\n8\n291\n0\n");
    Parser copied(source), assigned;
    assigned = source;
    for (Parser* clone : {&copied, &assigned}) {
        parse(*clone, "70\n58\n4\nTail\n100\nAcDbVisualStyle\n70\n2\n");
        t.expect(clone->type == 8 && clone->desc == "Original",
                 "copy and assignment own the latched tail scope without reopening on a repeated subclass");
        clone->reset();
        parse(*clone, "4\nLegacy\n70\n12\n");
        t.expect(clone->type == 12 && clone->desc == "Legacy",
                 "explicit reset restores markerless older basic parsing");
    }
    source.reset();
    parse(source, "100\nForeign\n70\n99\n2\nForeignName\n291\n1\n");
    t.expect(source.type == 0 && source.desc.empty(),
             "foreign subclass alone cannot assign visual-style basic metadata");
    parse(source, "100\nAcDbVisualStyle\n2\nNew\n70\n6\n");
    t.expect(source.type == 6 && source.desc == "New",
             "foreign subclass fields cannot trigger the visual-style property-tail latch");
}

void testGeoDataVersionedMappings(TestContext& t) {
    const auto nonce = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto directory = std::filesystem::temp_directory_path()
        / ("libdxfrw-geodata-version-" + std::to_string(nonce));
    std::error_code error;
    if (!std::filesystem::create_directory(directory, error) || error) {
        t.expect(false, "temporary GEODATA directory is available");
        return;
    }
    struct Cleanup {
        std::filesystem::path path;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    struct VersionCase {
        const char* target;
        std::int32_t objectVersion;
    };
    const VersionCase versions[] = {
        {"AC1021", 1}, {"AC1024", 2}, {"AC1027", 3}
    };
    for (const bool binary : {false, true}) {
        for (const VersionCase& version : versions) {
            const std::string stem = std::string("geodata-")
                + version.target + (binary ? "-binary" : "-ascii");
            const auto path = directory / (stem + ".dxf");
            std::vector<int> expectedCodes;
            const bool generated = writeGeoDataVersionControl(
                path, binary, version.target, version.objectVersion,
                expectedCodes);
            FixtureInterface importer;
            dx_data data;
            const bool imported = generated
                && importer.fileImport(path.string(), &data, false);
            const auto geodataRaw = std::find_if(
                importer.rawObjects.begin(), importer.rawObjects.end(),
                [](const DRW_RawDxfObject& raw) {
                    return raw.name == "GEODATA";
                });
            const auto following = std::find_if(
                importer.rawObjects.begin(), importer.rawObjects.end(),
                [](const DRW_RawDxfObject& raw) {
                    return raw.name == "ACDBPLACEHOLDER";
                });
            std::vector<int> actualCodes;
            if (geodataRaw != importer.rawObjects.end()) {
                actualCodes.reserve(geodataRaw->groups.size());
                for (const DRW_Variant& group : geodataRaw->groups)
                    actualCodes.push_back(group.code());
            }
            std::vector<int> expectedGeoCodes;
            if (expectedCodes.size() > 1u) {
                const auto followingObject = std::find(
                    expectedCodes.begin() + 1, expectedCodes.end(), 0);
                expectedGeoCodes.assign(expectedCodes.begin() + 1,
                                        followingObject);
            }
            const bool rawSequencePreserved = geodataRaw
                    != importer.rawObjects.end()
                && actualCodes == expectedGeoCodes
                && geodataRaw->groups.size() == geodataRaw->rawValues.size()
                && geodataRaw->handle == 0x700u
                && geodataRaw->parentHandle == 0x2u;
            const bool objectBoundaryPreserved = importer.rawObjects.size() == 2u
                && following != importer.rawObjects.end()
                && following->handle == 0x701u;
            bool typedValuesMatch = importer.geoData.size() == 1u
                && importer.geoData.front().m_version == version.objectVersion
                && importer.geoData.front().handle == 0x700u
                && importer.geoData.front().parentHandle == 0x2u
                && importer.geoData.front().m_hostBlockHandle == 0x3u
                && (version.objectVersion == 1
                    || importer.geoData.front().m_coordinatesType == 2);
            bool legacyLifecycleMatches = true;
            if (version.objectVersion == 1 && typedValuesMatch) {
                const DRW_GeoData& geo = importer.geoData.front();
                typedValuesMatch = geo.m_coordinatesType == 0
                    && geo.m_legacy.m_controlFlags == 2
                    && geo.m_designPoint.x == 10.125
                    && geo.m_designPoint.y == 20.125
                    && geo.m_designPoint.z == 30.125
                    && geo.m_referencePoint.x == 0.0
                    && geo.m_referencePoint.y == 0.0
                    && geo.m_referencePoint.z == 0.0
                    && geo.m_legacy.m_secondWcsPoint.x == 11.125
                    && geo.m_legacy.m_secondWcsPoint.y == 21.125
                    && geo.m_legacy.m_secondWcsPoint.z == 31.125
                    && geo.m_legacy.m_geolocation[0] == 40.125
                    && geo.m_legacy.m_geolocation[1] == 41.125
                    && geo.m_legacy.m_geolocation[2] == 42.125
                    && geo.m_legacy.m_drawingScales[0] == 43.125
                    && geo.m_legacy.m_drawingScales[1] == 44.125
                    && geo.m_legacy.m_drawingScales[2] == 45.125
                    && geo.m_legacy.m_mapUnits == 46.125
                    && geo.m_legacy.m_northDirectionAngle == 52.125
                    && geo.m_legacy.m_dwgUnits == 91
                    && geo.m_upDirection.x == 210.125
                    && geo.m_upDirection.y == 220.125
                    && geo.m_upDirection.z == 230.125
                    && geo.m_points.size() == 1u
                    && geo.m_points.front().m_source.x == 12.125
                    && geo.m_points.front().m_source.y == 22.125
                    && geo.m_points.front().m_destination.x == 13.125
                    && geo.m_points.front().m_destination.y == 23.125
                    && geo.m_faces.size() == 1u
                    && geo.m_faces.front().m_index1 == 1
                    && geo.m_faces.front().m_index2 == 2
                    && geo.m_faces.front().m_index3 == 3
                    && geo.m_coordinateSystemDefinition
                        == "legacy-coordinate-definition"
                    && geo.m_geoRssTag == "legacy-georss"
                    && geo.m_legacy.m_coordinateSystemDescription
                        == "legacy-coordinate-description"
                    && geo.m_legacy.m_coordinateSystemDatum == "legacy-datum"
                    && geo.m_observationFromTag == "legacy-observation-tag"
                    && geo.m_observationToTag == "legacy-observation-to"
                    && geo.m_observationCoverageTag
                        == "legacy-observation-coverage"
                    && geo.m_legacy.m_civil.m_present
                    && geo.m_legacy.m_civil.m_transformLocalToGrid
                    && geo.m_legacy.m_civil.m_localReferencePoint[0] == 14.125
                    && geo.m_legacy.m_civil.m_localReferencePoint[1] == 24.125
                    && geo.m_legacy.m_civil.m_gridReferencePoint[0] == 15.125
                    && geo.m_legacy.m_civil.m_gridReferencePoint[1] == 25.125
                    && geo.m_legacy.m_civil.m_localReferencePointNumber == 1
                    && geo.m_legacy.m_civil.m_gridReferencePointNumber == 94
                    && geo.m_legacy.m_civil.m_useRotationPoints
                    && geo.m_legacy.m_civil.m_localRotationPoint[0] == 16.125
                    && geo.m_legacy.m_civil.m_localRotationPoint[1] == 26.125
                    && geo.m_legacy.m_civil.m_gridRotationPoint[0] == 17.125
                    && geo.m_legacy.m_civil.m_gridRotationPoint[1] == 27.125
                    && geo.m_legacy.m_civil.m_rotationAngle == 54.125
                    && geo.m_legacy.m_civil.m_gridAzimuth == 140.125
                    && geo.m_legacy.m_civil.m_scaleEstimationMethod == 2
                    && geo.m_legacy.m_civil.m_ambiguous141Value == 141.125
                    && geo.m_legacy.m_civil.m_enableSeaLevelCorrection
                    && geo.m_legacy.m_civil.m_seaLevelElevation == 142.125
                    && geo.m_legacy.m_civil.m_coordinateProjectionRadius
                        == 143.125;
                DRW_GeoData copied(geo);
                DRW_GeoData assigned;
                assigned = geo;
                legacyLifecycleMatches = copied.m_legacy.m_controlFlags == 2
                    && copied.m_legacy.m_civil.m_localRotationPoint[1] == 26.125
                    && copied.m_legacy.m_coordinateSystemDatum == "legacy-datum"
                    && assigned.m_legacy.m_controlFlags == 2
                    && assigned.m_legacy.m_civil.m_gridReferencePointNumber == 94
                    && assigned.m_legacy.m_coordinateSystemDescription
                        == "legacy-coordinate-description";
                copied.reset();
                legacyLifecycleMatches = legacyLifecycleMatches
                    && copied.m_legacy.m_controlFlags == 0
                    && !copied.m_legacy.m_civil.m_present
                    && copied.m_legacy.m_civil.m_ambiguous141Value == 0.0
                    && copied.m_legacy.m_coordinateSystemDatum.empty();
            }
            if (version.objectVersion >= 2 && typedValuesMatch) {
                const DRW_GeoData& geo = importer.geoData.front();
                typedValuesMatch = geo.m_horizontalUnitScale == 40.125
                    && geo.m_verticalUnitScale == 41.125
                    && geo.m_horizontalUnits == 91
                    && geo.m_verticalUnits == 92
                    && geo.m_upDirection.x == 210.125
                    && geo.m_upDirection.y == 220.25
                    && geo.m_upDirection.z == 230.375
                    && geo.m_northDirection.x == 12.125
                    && geo.m_northDirection.y == 22.25
                    && geo.m_points.size() == 1u
                    && geo.m_points.front().m_source.x == 13.125
                    && geo.m_points.front().m_source.y == 23.25
                    && geo.m_points.front().m_destination.x == 14.125
                    && geo.m_points.front().m_destination.y == 24.25
                    && geo.m_faces.size() == 1u
                    && geo.m_faces.front().m_index1 == 1
                    && geo.m_faces.front().m_index2 == 2
                    && geo.m_faces.front().m_index3 == 3;
            }
            const std::string label = (binary ? "binary " : "ASCII ")
                + stem + " preserves ordered GEODATA raw groups, object "
                         "boundary, and current typed control values";
            t.expect(imported && rawSequencePreserved
                         && objectBoundaryPreserved && typedValuesMatch
                         && legacyLifecycleMatches,
                     label.c_str());
        }
    }
}

bool writeHiddenZeroHeightAttribDxf(const std::filesystem::path& path,
                                    bool binary,
                                    bool malformedFooter = false) {
    std::ofstream stream(path, std::ios::binary | std::ios::trunc);
    if (!stream)
        return false;
    if (binary)
        stream.write("AutoCAD Binary DXF\r\n\x1a\0", 22);
    std::unique_ptr<dxfWriter> writer = binary
        ? std::unique_ptr<dxfWriter>(new dxfWriterBinary(&stream))
        : std::unique_ptr<dxfWriter>(new dxfWriterAscii(&stream));
    writer->setVersion("AC1021", true);
    const auto string = [&writer](int code, const char* value) {
        return writer->writeString(code, value);
    };
    const auto integer = [&writer](int code, int value) {
        return writer->writeInt16(code, value);
    };
    const auto real = [&writer](int code, double value) {
        return writer->writeDouble(code, value);
    };

    const bool written = string(0, "SECTION") && string(2, "HEADER")
        && string(9, "$ACADVER") && string(1, "AC1021")
        && string(0, "ENDSEC")
        && string(0, "SECTION") && string(2, "TABLES")
        && string(0, "TABLE") && string(2, "APPID")
        && string(5, "C0") && string(330, "0")
        && string(100, "AcDbSymbolTable") && integer(70, 1)
        && string(0, "APPID") && string(5, "C1") && string(330, "C0")
        && string(100, "AcDbSymbolTableRecord")
        && string(100, "AcDbRegAppTableRecord")
        && string(2, "SEQEND_TEST") && integer(70, 0)
        && string(0, "ENDTAB") && string(0, "ENDSEC")
        && string(0, "SECTION") && string(2, "ENTITIES")
        && string(0, "INSERT") && string(5, "5F00")
        && string(100, "AcDbEntity")
        && string(8, "0") && string(100, "AcDbBlockReference")
        && string(2, "LOCAL_ATTRIB_OWNER")
        && real(10, 1.0) && real(20, 2.0) && real(30, 3.0)
        && integer(66, 1)
        && string(0, "ATTRIB") && string(100, "AcDbEntity")
        && string(8, "0") && string(100, "AcDbText")
        && real(10, 4.0) && real(20, 5.0) && real(30, 6.0)
        && real(40, 0.0) && string(1, "HIDDEN_ZERO_VALUE")
        && string(7, "STANDARD") && string(100, "AcDbAttribute")
        && integer(70, 1) && string(2, "HIDDEN_ZERO_TAG")
        && string(0, "SEQEND") && string(5, "5F02")
        && string(330, "5F00") && integer(67, 1)
        && string(8, "SEQ_LAYER") && integer(62, 3)
        && string(102, "{CUSTOM_FOOTER") && string(1, "SEQEND_META")
        && string(102, malformedFooter ? "BROKEN_CLOSE" : "}")
        && string(1001, "SEQEND_TEST") && string(1000, "SEQEND_XDATA")
        && string(0, "LINE") && string(100, "AcDbEntity")
        && string(8, "0") && string(100, "AcDbLine")
        && real(10, 10.0) && real(20, 20.0) && real(30, 30.0)
        && real(11, 40.0) && real(21, 50.0) && real(31, 60.0)
        && string(0, "INSERT") && string(5, "5F10")
        && string(100, "AcDbEntity") && string(8, "0")
        && string(100, "AcDbBlockReference")
        && string(2, "LOCAL_EMPTY_ATTRIB_OWNER")
        && real(10, 7.0) && real(20, 8.0) && real(30, 9.0)
        && integer(66, 1)
        && string(0, "SEQEND") && string(5, "5F12")
        && string(330, "5F10") && integer(67, 1)
        && string(8, "EMPTY_CHAIN_FOOTER")
        && string(0, "ENDSEC") && string(0, "EOF");
    stream.flush();
    return written && !writer->hasWriteError() && stream.good();
}

