    t.expect(imported, "authored XREF path source imports through dx_iface");
    if (!imported)
        return;
    const auto addFooterGraph = [&inputData](std::uint32_t dictionaryHandle,
                                             std::uint32_t ownerHandle,
                                             std::uint32_t recordHandle,
                                             const char* marker) {
        DRW_Dictionary dictionary;
        dictionary.handle = dictionaryHandle;
        dictionary.parentHandle = ownerHandle;
        dictionary.m_entries.push_back({"FOOTER_RECORD", recordHandle});
        inputData.dictionaries.push_back(std::move(dictionary));
        DRW_XRecord record;
        record.handle = recordHandle;
        record.parentHandle = dictionaryHandle;
        record.m_dataEntries.emplace_back(320, std::string("DEAD"));
        record.m_dataEntries.emplace_back(1, std::string(marker));
        inputData.xRecords.push_back(std::move(record));
    };
    addFooterGraph(0x12u, 0xA3u, 0x15u, "xref-footer-graph");
    addFooterGraph(0x14u, 0xB3u, 0x16u, "model-footer-graph");
    addFooterGraph(0x17u, 0xB5u, 0x18u, "paper-footer-graph");
    const auto findXref = [](const dx_data& data) {
        return std::find_if(data.blocks.cbegin(), data.blocks.cend(),
            [](const dx_ifaceBlock* block) {
                return block != nullptr && block->name == "XREF_TEST";
            });
    };
    const auto findBlockByName = [](const dx_data& data, const char* name) {
        return std::find_if(data.blocks.cbegin(), data.blocks.cend(),
            [name](const dx_ifaceBlock* block) {
                return block != nullptr && block->name == name;
            });
    };
    const auto inputXref = findXref(inputData);
    t.expect(inputXref != inputData.blocks.end()
                 && (*inputXref)->flags == 36
                 && (*inputXref)->xrefUnloaded
                 && (*inputXref)->layer == "XREF_DEF_LAYER"
                 && (*inputXref)->lineType == "CONTINUOUS"
                 && (*inputXref)->color == 3
                 && (*inputXref)->color24 == 1193046
                 && (*inputXref)->colorName == "SampleColorBook$DeepBlue"
                 && (*inputXref)->transparency == 33554560
                 && (*inputXref)->ltypeScale == 2.5
                 && !(*inputXref)->visible
                 && (*inputXref)->shadow == DRW::IgnoreShadows
                 && (*inputXref)->lWeight == DRW_LW_Conv::width07
                 && (*inputXref)->appData.size() == 1
                 && (*inputXref)->xrefPath == xrefPath
                 && (*inputXref)->hasDescription
                 && (*inputXref)->description == description
                 && (*inputXref)->extData.size() == expectedXdata.size(),
             "DXF import retains XREF path, description, and BLOCK XDATA");
    if (inputXref == inputData.blocks.end())
        return;
    const auto hasExpectedAppData = [&expectedAppData](const DRW_Block& block) {
        if (block.appData.size() != 1)
            return false;
        const auto& group = block.appData.front();
        if (group.size() != expectedAppData.size())
            return false;
        auto actual = group.cbegin();
        for (const auto& expected : expectedAppData) {
            if (actual->code() != expected.first)
                return false;
            if (actual->type() != DRW_Variant::STRING
                || actual->content.s == nullptr
                || *actual->content.s != expected.second)
                return false;
            ++actual;
        }
        return true;
    };
    t.expect(hasExpectedAppData(**inputXref),
             "BLOCK appData retains ordered group-102 and text values");
    const auto hasExpectedXdata = [&expectedXdata](const DRW_Block& block) {
        if (block.extData.size() != expectedXdata.size())
            return false;
        for (std::size_t index = 0; index < expectedXdata.size(); ++index) {
            const DRW_Variant* value = block.extData[index].get();
            if (value == nullptr || value->code() != expectedXdata[index].first)
                return false;
            if (value->type() == DRW_Variant::STRING) {
                if (value->content.s == nullptr
                    || *value->content.s != expectedXdata[index].second)
                    return false;
            } else if (value->type() == DRW_Variant::INTEGER) {
                if (value->content.i != 42
                    || expectedXdata[index].second != "42")
                    return false;
            } else {
                return false;
            }
        }
        return true;
    };
    t.expect(hasExpectedXdata(**inputXref),
             "BLOCK XDATA retains ordered typed strings, braces, and integer");
    const dx_ifaceBlock* importedXref = *inputXref;
    const bool footerFieldsRetained = importedXref->hasEndBlockData
        && importedXref->endBlockData.getIsEnd()
        && importedXref->endBlockData.space == DRW::PaperSpace
        && importedXref->endBlockData.reactorHandles.size() == 1u
        && importedXref->endBlockData.xDictHandle != 0u
        && importedXref->endBlockData.material != DRW::MaterialByLayer
        && importedXref->endBlockData.fullVisualStyleHandle != 0u
        && importedXref->endBlockData.plotStyle != DRW::DefaultPlotStyle;
    t.expect(footerFieldsRetained,
             "ENDBLK carrier retains space, reactor, xDictionary, and style handles");
