        return block != nullptr && block->hasEndBlockData
            && block->endBlockData.getIsEnd()
            && block->endBlockData.space == space
            && block->endBlockData.color == color
            && block->endBlockData.visible == false
            && block->endBlockData.shadow == DRW::IgnoreShadows
            && block->endBlockData.lWeight == lineWeight
            && block->endBlockData.reactorHandles.size() == 1u
            && block->endBlockData.xDictHandle != 0u
            && block->endBlockData.material != DRW::MaterialByLayer
            && block->endBlockData.fullVisualStyleHandle != 0u
            && block->endBlockData.plotStyle != DRW::DefaultPlotStyle
            && block->endBlockData.extData.size() == 2u;
