    const auto readAppDataHandle = [](const DRW_Block& block,
                                     const char* groupName, int code,
                                     std::uint32_t& handle) {
        handle = 0;
        std::size_t matches = 0;
        for (const auto& group : block.appData) {
            if (group.empty())
                continue;
            const DRW_Variant& opener = group.front();
            if (opener.code() != 102 || opener.type() != DRW_Variant::STRING
                || opener.content.s == nullptr)
                continue;
            std::string marker = *opener.content.s;
            if (!marker.empty() && marker.front() == '{')
                marker.erase(marker.begin());
            for (char& character : marker) {
                if (character >= 'a' && character <= 'z')
                    character = static_cast<char>(character - 'a' + 'A');
            }
            if (marker != groupName)
                continue;
            for (const DRW_Variant& value : group) {
                if (value.code() != code)
                    continue;
                if (value.type() != DRW_Variant::STRING
                    || value.content.s == nullptr || ++matches != 1u)
                    return false;
                const std::string& text = *value.content.s;
                std::uint64_t parsed = 0;
                const auto result = std::from_chars(
                    text.data(), text.data() + text.size(), parsed, 16);
                if (result.ec != std::errc{}
                    || result.ptr != text.data() + text.size()
                    || parsed == 0
                    || parsed > std::numeric_limits<std::uint32_t>::max())
                    return false;
                handle = static_cast<std::uint32_t>(parsed);
            }
        }
        return matches == 1u;
    };
    std::uint32_t sourceAppDataReactor = 0;
