bool dxfHeaderUnknownStringIs(const DRW_Header& header, const char* key,
                              int code, const std::string& expected) {
    const auto found = header.vars.find(key);
    return found != header.vars.end() && found->second != nullptr
        && found->second->type() == DRW_Variant::STRING
        && found->second->code() == code
        && *found->second->content.s == expected;
}

bool dxfHeaderUnknownIntIs(const DRW_Header& header, const char* key,
                           int code, int expected) {
    const auto found = header.vars.find(key);
    return found != header.vars.end() && found->second != nullptr
        && found->second->type() == DRW_Variant::INTEGER
        && found->second->code() == code
        && found->second->i_val() == expected;
}

