using namespace materialConsumerControls;
using A=DxIfaceMaterialReferenceTestAccess;
const std::string initialDescription="source description café^A\\U+1234";
const std::string editedDescription="edited description café^A\\U+1234";
struct Scalars {int flags=0,fill=256;double start=90.0,end=90.0;};
using AciColors=std::array<int,2>;
using LtypeNames=std::array<std::string,2>;
void setScalars(dx_data& data,const Scalars& value) {
    auto& style=data.mLineStyles.front();style.flags=value.flags;style.fillColor=value.fill;style.startAngle=value.start;style.endAngle=value.end;
}
Tags recipe(const std::string& version,bool binary=false,bool description=true,bool angles=true,unsigned scalarMask=15u) {
    Tags fields{{0,"SECTION"},{2,"HEADER"},{9,"$ACADVER"},{1,version},{9,"$DWGCODEPAGE"},{3,"ANSI_1252"},{0,"ENDSEC"},
        {0,"SECTION"},{2,"TABLES"},{0,"TABLE"},{2,"LTYPE"},{5,"100"},{100,"AcDbSymbolTable"},{70,"2"},
        {0,"LTYPE"},{5,"101"},{330,"100"},{100,"AcDbSymbolTableRecord"},{100,"AcDbLinetypeTableRecord"},{2,"ByLayer"},{70,"0"},{3,""},{72,"65"},{73,"0"},{40,"0"},
        {0,"LTYPE"},{5,"102"},{330,"100"},{100,"AcDbSymbolTableRecord"},{100,"AcDbLinetypeTableRecord"},{2,"Continuous"},{70,"0"},{3,""},{72,"65"},{73,"0"},{40,"0"},{0,"ENDTAB"},{0,"ENDSEC"},
        {0,"SECTION"},{2,"OBJECTS"},{0,"DICTIONARY"},{5,"C"},{330,"0"},{100,"AcDbDictionary"},{280,"0"},{281,"1"},
        {3,"ACAD_MLINESTYLE"},{350,"A"},{0,"DICTIONARY"},{5,"A"},{330,"C"},{100,"AcDbDictionary"},{280,"0"},{281,"1"},
        {3,"BODY_STYLE"},{350,"D"},{0,"MLINESTYLE"},{5,"D"},{330,"A"},{100,"AcDbMlineStyle"},{2,"BODY_STYLE"}};
    if(scalarMask&1u)fields.emplace_back(70,"0");
    if(description)fields.emplace_back(3,materialBodyControls::encodedText(initialDescription,version,binary,"ANSI_1252"));
    if(scalarMask&2u)fields.emplace_back(62,"256");
    if(angles&&(scalarMask&4u))fields.emplace_back(51,"90");if(angles&&(scalarMask&8u))fields.emplace_back(52,"90");
    fields.insert(fields.end(),{{71,"2"},{49,"0.5"},{62,"1"},{6,"ByLayer"},{49,"-0.25"},{62,"3"},{6,"Continuous"},{301,"opaque-mline-tail"},
        {0,"ENDSEC"},{0,"EOF"}});return fields;
}
DRW_RawDxfObject& raw(dx_data& data) {
    for(auto& row:data.rawNamedResourceObjects)if(row.handle==data.mLineStyles.front().handle)return row;
    throw std::runtime_error("MLINESTYLE raw source missing");
}
void rawValue(dx_data& data,int code,const std::string& text,bool binary,const std::string& version="AC1027") {
    auto& row=raw(data);
    for(std::size_t i=0u;i<row.groups.size();++i)if(row.groups[i].code()==code) {
        if(code==2||code==3||code==6||code==301)row.groups[i]=DRW_Variant(code,UTF8STRING(materialBodyControls::encodedText(text,version,binary,"ANSI_1252")));
        else if(code==70||code==62)row.groups[i]=DRW_Variant(code,std::int32_t(std::stoi(text)));
        else row.groups[i]=DRW_Variant(code,std::stod(text));
        if(row.hasRawValues)row.rawValues[i]=(code==2||code==3||code==6||code==301)?materialBodyControls::encodedText(text,version,binary,"ANSI_1252"):text;
        return;
    }
    throw std::runtime_error("MLINESTYLE raw role missing");
}
std::vector<std::size_t> elementColorSlots(const DRW_RawDxfObject& record) {
    std::vector<std::size_t> result;unsigned depth=0u,elements=0u;bool body=false;
    for(std::size_t i=0u;i<record.groups.size();++i) {
        const auto& field=record.groups[i];const auto code=field.code();
        if(code==102){if(field.type()!=DRW_Variant::STRING||!field.content.s)throw std::runtime_error("ACI application marker");
            if(*field.content.s=="}"){if(!depth)throw std::runtime_error("ACI application depth");--depth;}else ++depth;continue;}
        if(depth)continue;
        if(code==100){body=field.type()==DRW_Variant::STRING&&field.content.s&&*field.content.s=="AcDbMlineStyle";continue;}
        if(!body)continue;if(code==49)++elements;
        if(code==62&&elements){if(result.size()!=elements-1u)throw std::runtime_error("ACI tuple color count");result.push_back(i);}
    }
    if(depth||result.size()!=elements)throw std::runtime_error("ACI tuple color scope");return result;
}
void rawElementColor(dx_data& data,std::size_t element,int color) {
    auto& record=raw(data);const auto slots=elementColorSlots(record);if(element>=slots.size())throw std::runtime_error("ACI element missing");
    record.groups[slots[element]]=DRW_Variant(62,std::int32_t(color));if(record.hasRawValues)record.rawValues[slots[element]]=std::to_string(color);
}
bool sameDoubleRepresentation(double a,double b) {
    std::uint64_t x=0u,y=0u;std::memcpy(&x,&a,sizeof(x));std::memcpy(&y,&b,sizeof(y));return x==y;
}
bool aciRawUnchanged(const DRW_RawDxfObject& a,const DRW_RawDxfObject& b) {
    if(a.name!=b.name||a.handle!=b.handle||a.parentHandle!=b.parentHandle||a.m_version!=b.m_version
        ||a.hasRawValues!=b.hasRawValues||a.rawValues!=b.rawValues||a.groups.size()!=b.groups.size())return false;
    for(std::size_t i=0u;i<a.groups.size();++i) {
        const auto& x=a.groups[i];const auto& y=b.groups[i];if(x.code()!=y.code()||x.type()!=y.type())return false;
        if(x.type()==DRW_Variant::STRING){if(!x.content.s||!y.content.s||*x.content.s!=*y.content.s)return false;}
        else if(x.type()==DRW_Variant::INTEGER){if(x.i_val()!=y.i_val())return false;}
        else if(x.type()==DRW_Variant::DOUBLE){if(!sameDoubleRepresentation(x.d_val(),y.d_val()))return false;}
        else return false;
    }
    return true;
}
bool modelValues(const dx_data& data,const std::string& description,double start=90.0,double end=90.0,double firstOffset=.5,int flags=0,int fill=256,const AciColors& colors=AciColors{{1,3}},const LtypeNames& names=LtypeNames{{"ByLayer","Continuous"}}) {
    if(data.mLineStyles.size()!=1u)return false;
    const auto& value=data.mLineStyles.front();
    return value.name=="BODY_STYLE"&&value.description==description&&static_cast<std::uint16_t>(value.flags)==static_cast<std::uint16_t>(flags)&&value.fillColor==fill
        &&value.startAngle==start&&value.endAngle==end
        &&std::signbit(value.startAngle)==std::signbit(start)&&std::signbit(value.endAngle)==std::signbit(end)&&value.elements.size()==2u
        &&value.elements[0].offset==firstOffset&&value.elements[0].color==colors[0]&&value.elements[0].linetype==names[0]
        &&value.elements[1].offset==-.25&&value.elements[1].color==colors[1]&&value.elements[1].linetype==names[1];
}
bool values(const std::filesystem::path& path,const std::string& description,double start=90.0,double end=90.0,double firstOffset=.5,int flags=0,int fill=256,const AciColors& colors=AciColors{{1,3}},const LtypeNames& names=LtypeNames{{"ByLayer","Continuous"}}) {
    dx_iface reader;dx_data data;return reader.fileImport(path.string(),&data,false)&&modelValues(data,description,start,end,firstOffset,flags,fill,colors,names);
}
bool proof(const std::filesystem::path& path,bool binary,const std::string& version,const std::string& description,bool descriptionPresent=true,double start=90.0,bool angles=true,const std::string& opaque="opaque-mline-tail",double firstOffset=.5,double end=90.0,int flags=0,int fill=256,unsigned scalarMask=15u,const AciColors& colors=AciColors{{1,3}},const LtypeNames& names=LtypeNames{{"ByLayer","Continuous"}}) {
    using Row=customDictionaryVarControls::Row;std::vector<Row> rows;
    for(const auto& field:materialBodyControls::physicalTags(path,binary)) {
        if(field.first==0){rows.push_back({field.second,{},{},{}});continue;}
        if(rows.empty())continue;auto& row=rows.back();row.fields.push_back(field);
        if(field.first==5&&row.id.empty())row.id=field.second;if(field.first==330&&row.owner.empty())row.owner=field.second;
    }
    const auto find=[&](const std::string& handle)->const Row*{const Row* result=nullptr;for(const auto& row:rows)if(row.id==handle){if(result)return nullptr;result=&row;}return result;};
    const auto entry=[&](const Row& row,const std::string& key)->const Row* {
        const Row* result=nullptr;for(std::size_t i=0u;i+1u<row.fields.size();++i)if(row.fields[i]==std::make_pair(3,key)) {
            if(result||row.fields[i+1u].first!=350)return nullptr;result=find(row.fields[i+1u].second);
        }return result;
    };
    const Row* root=nullptr;for(const auto& row:rows)if(row.type=="DICTIONARY"&&row.owner=="0"){if(root)return false;root=&row;}
    if(!root)return false;const auto* owner=entry(*root,"ACAD_MLINESTYLE");if(!owner||owner->type!="DICTIONARY"||owner->owner!=root->id)return false;
    const auto* style=entry(*owner,"BODY_STYLE");if(!style||style->type!="MLINESTYLE"||style->owner!=owner->id)return false;
    std::map<int,std::vector<std::string>> fields;for(const auto& field:style->fields)fields[field.first].push_back(field.second);
    const auto nums=[&](int code,const std::vector<double>& expected){if(fields[code].size()!=expected.size())return false;for(std::size_t i=0u;i<expected.size();++i)if(std::stod(fields[code][i])!=expected[i]||std::signbit(std::stod(fields[code][i]))!=std::signbit(expected[i]))return false;return true;};
    const bool flagMatched=fields[70].size()==((scalarMask&1u)?1u:0u)
        &&(!(scalarMask&1u)||(std::stoll(fields[70].front())>=-32768&&std::stoll(fields[70].front())<=65535
            &&static_cast<std::uint16_t>(std::stoll(fields[70].front()))==static_cast<std::uint16_t>(flags)));
    return fields[2]==std::vector<std::string>{"BODY_STYLE"}&&fields[3]==(descriptionPresent?std::vector<std::string>{materialBodyControls::encodedText(description,version,binary,"ANSI_1252")}:std::vector<std::string>{})
        &&flagMatched&&nums(62,(scalarMask&2u)?std::vector<double>{double(fill),double(colors[0]),double(colors[1])}:std::vector<double>{double(colors[0]),double(colors[1])})
        &&nums(51,(angles&&(scalarMask&4u))?std::vector<double>{start}:std::vector<double>{})&&nums(52,(angles&&(scalarMask&8u))?std::vector<double>{end}:std::vector<double>{})
        &&nums(71,{2})&&nums(49,{firstOffset,-.25})&&fields[6]==std::vector<std::string>{names[0],names[1]}&&fields[301]==std::vector<std::string>{opaque};
}
bool aciLiteral(const std::filesystem::path& path,bool binary,const AciColors& colors,int fill=256) {
    std::vector<std::pair<int,std::string>> selected;bool style=false,body=false;unsigned depth=0u,styles=0u;
    for(const auto& field:materialBodyControls::physicalTags(path,binary)) {
        if(field.first==0){style=field.second=="MLINESTYLE";body=false;depth=0u;if(style)++styles;continue;}
        if(!style)continue;
        if(field.first==102){if(field.second=="}"){if(!depth)return false;--depth;}else ++depth;continue;}
        if(depth)continue;if(field.first==100){body=field.second=="AcDbMlineStyle";continue;}
        if(body&&(field.first==49||field.first==62||field.first==6))selected.push_back(field);
    }
    const std::array<int,7> codes{{62,49,62,6,49,62,6}};
    if(styles!=1u||selected.size()!=codes.size())return false;
    for(std::size_t i=0u;i<codes.size();++i)if(selected[i].first!=codes[i])return false;
    std::int64_t a=0,b=0,c=0;
    return dx_raster_output::integer(selected[0].second,a)&&a==fill
        &&dx_raster_output::integer(selected[2].second,b)&&b==colors[0]
        &&dx_raster_output::integer(selected[5].second,c)&&c==colors[1]
        &&std::stod(selected[1].second)==.5&&std::stod(selected[4].second)==-.25
        &&selected[3].second=="ByLayer"&&selected[6].second=="Continuous";
}
bool aciProof(const std::filesystem::path& path,bool binary,const AciColors& colors,const std::string& description=initialDescription,int fill=256) {
    return proof(path,binary,"AC1027",description,true,90,true,"opaque-mline-tail",.5,90,0,fill,15u,colors)
        &&values(path,description,90,90,.5,0,fill,colors)&&aciLiteral(path,binary,colors,fill);
}
bool ltypeBasicProof(const std::filesystem::path& path,bool binary,const LtypeNames& names) {
    return proof(path,binary,"AC1027",initialDescription,true,90,true,"opaque-mline-tail",.5,90,0,256,15u,{{1,3}},names)
        &&values(path,initialDescription,90,90,.5,0,256,{{1,3}},names);
}
bool scalarProof(const std::filesystem::path& path,bool binary,const std::string& version,const std::string& description,const Scalars& wanted,unsigned mask=15u) {
    return proof(path,binary,version,description,true,wanted.start,true,"opaque-mline-tail",.5,wanted.end,wanted.flags,wanted.fill,mask)
        &&values(path,description,wanted.start,wanted.end,.5,wanted.flags,wanted.fill);
}
Tags textRecipe(const std::string& version,bool binary,int role,const std::string& text,unsigned mask=15u) {
    auto fields=recipe(version,binary,true,true,mask);bool style=false;
    const auto encoded=materialBodyControls::encodedText(text,version,binary,"ANSI_1252");
    for(auto& field:fields) {
        if(field.first==0)style=field.second=="MLINESTYLE";
        if(role==2&&field.first==3&&field.second=="BODY_STYLE")field.second=encoded;
        if(role==2&&style&&field.first==2)field.second=encoded;
        if(role==6&&field.first==2&&field.second=="Continuous")field.second=encoded;
        if(role==6&&style&&field.first==6&&field.second=="Continuous")field.second=encoded;
    }
    return fields;
}
bool textProof(const std::filesystem::path& path,bool binary,const std::string& version,
        const std::string& page,const std::string& name,const std::string& linetype,
        const std::string& description,const Scalars& scalars=Scalars{},unsigned mask=15u) {
    dx_iface reader;dx_data data;
    if(!reader.fileImport(path.string(),&data,false)||data.mLineStyles.size()!=1u)return false;
    const auto& value=data.mLineStyles.front();
    if(value.name!=name||value.description!=description||value.flags!=scalars.flags||value.fillColor!=scalars.fill
        ||value.startAngle!=scalars.start||value.endAngle!=scalars.end||value.elements.size()!=2u
        ||value.elements[0].offset!=.5||value.elements[0].color!=1||value.elements[0].linetype!="ByLayer"
        ||value.elements[1].offset!=-.25||value.elements[1].color!=3||value.elements[1].linetype!=linetype)return false;
    unsigned linetypes=0u;for(const auto& line:data.lineTypes)if(line.name==linetype)++linetypes;
    if(linetypes!=1u)return false;
    using Row=customDictionaryVarControls::Row;std::vector<Row> rows;
    for(const auto& field:materialBodyControls::physicalTags(path,binary)) {
        if(field.first==0){rows.push_back({field.second,{},{},{}});continue;}
        if(rows.empty())continue;auto& row=rows.back();row.fields.push_back(field);
        if(field.first==5&&row.id.empty())row.id=field.second;
        if(field.first==330&&row.owner.empty())row.owner=field.second;
    }
    const auto find=[&](const std::string& handle)->const Row* {
        const Row* result=nullptr;for(const auto& row:rows)if(row.id==handle){if(result)return nullptr;result=&row;}return result;
    };
    const auto entry=[&](const Row& row,const std::string& key)->const Row* {
        const Row* result=nullptr;
        for(std::size_t i=0u;i+1u<row.fields.size();++i)if(row.fields[i]==std::make_pair(3,key)) {
            if(result||row.fields[i+1u].first!=350)return nullptr;result=find(row.fields[i+1u].second);
        }
        return result;
    };
    const auto encoded=[&](const std::string& text){return materialBodyControls::encodedText(text,version,binary,page);};
    const Row* root=nullptr;for(const auto& row:rows)if(row.type=="DICTIONARY"&&row.owner=="0"){if(root)return false;root=&row;}
    if(!root)return false;const auto* owner=entry(*root,"ACAD_MLINESTYLE");
    if(!owner||owner->type!="DICTIONARY"||owner->owner!=root->id)return false;
    const auto* style=entry(*owner,encoded(name));
    if(!style||style->type!="MLINESTYLE"||style->owner!=owner->id)return false;
    std::map<int,std::vector<std::string>> fields;for(const auto& field:style->fields)fields[field.first].push_back(field.second);
    const auto numbers=[&](int code,const std::vector<double>& expected) {
        if(fields[code].size()!=expected.size())return false;
        for(std::size_t i=0u;i<expected.size();++i)if(std::stod(fields[code][i])!=expected[i])return false;
        return true;
    };
    unsigned linetypeBodies=0u;
    for(const auto& row:rows)if(row.type=="LTYPE")for(const auto& field:row.fields)
        if(field==std::make_pair(2,encoded(linetype)))++linetypeBodies;
    return linetypeBodies==1u&&fields[2]==std::vector<std::string>{encoded(name)}
        &&fields[3]==std::vector<std::string>{encoded(description)}
        &&fields[6]==std::vector<std::string>{"ByLayer",encoded(linetype)}
        &&fields[301]==std::vector<std::string>{"opaque-mline-tail"}
        &&numbers(70,(mask&1u)?std::vector<double>{double(scalars.flags)}:std::vector<double>{})
        &&numbers(62,(mask&2u)?std::vector<double>{double(scalars.fill),1,3}:std::vector<double>{1,3})
        &&numbers(51,(mask&4u)?std::vector<double>{scalars.start}:std::vector<double>{})
        &&numbers(52,(mask&8u)?std::vector<double>{scalars.end}:std::vector<double>{})
        &&numbers(71,{2})&&numbers(49,{.5,-.25});
}
bool peer(const std::filesystem::path& input,const std::filesystem::path& output,bool binary) {
    dx_iface adapter;dx_data data;if(!adapter.fileImport(input.string(),&data,false))return false;unsigned edited=0u;
    for(auto& value:data.mLineStyles)if(value.name=="PeerMline"){value.description="edited peer café^A\\U+1234";++edited;}
    return edited==1u&&adapter.fileExport(output.string(),data.sourceVersion,binary,&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
}
bool scalarPeer(const std::filesystem::path& input,const std::filesystem::path& output,bool binary) {
    dx_iface adapter;dx_data data;if(!adapter.fileImport(input.string(),&data,false))return false;unsigned edited=0u;
    for(auto& value:data.mLineStyles)if(value.name=="PeerMline") {
        value.description="edited peer café^A\\U+1234";value.flags=273;value.fillColor=6;value.startAngle=22.5;value.endAngle=157.5;++edited;
    }
    return edited==1u&&adapter.fileExport(output.string(),data.sourceVersion,binary,&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
}
bool textPeer(const std::filesystem::path& input,const std::filesystem::path& output,bool binary,std::string_view page) {
    dx_iface adapter;dx_data data;if(!adapter.fileImport(input.string(),&data,false))return false;
    if(!page.empty()) {
        auto header=data.headerC.vars.find("$DWGCODEPAGE");
        if(header==data.headerC.vars.end()||!header->second||!header->second->content.s)return false;
        *header->second->content.s=std::string(page);
    }
    return adapter.fileExport(output.string(),data.sourceVersion,binary,&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
}
bool aciPeer(const std::filesystem::path& input,const std::filesystem::path& output,bool binary) {
    dx_iface adapter;dx_data data;if(!adapter.fileImport(input.string(),&data,false))return false;DRW_MLineStyle* selected=nullptr;
    for(const auto& dictionary:data.dictionaries)for(const auto& entry:dictionary.m_entries)if(entry.m_name=="PeerMline")
        for(auto& style:data.mLineStyles)if(style.handle==entry.m_handle&&style.parentHandle==dictionary.handle) {
            if(selected)return false;selected=&style;
        }
    if(!selected||selected->elements.size()!=2u)return false;selected->elements[0].color=0;selected->elements[1].color=256;
    return adapter.fileExport(output.string(),data.sourceVersion,binary,&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
}
Tags aciScopedRecipe(bool binary) {
    auto fields=recipe("AC1027",binary);const auto where=std::find(fields.begin(),fields.end(),std::make_pair(49,std::string("0.5")));
    if(where==fields.end())throw std::runtime_error("ACI offset witness missing");
    fields.insert(where+1,{{102,"{ACI_META"},{62,"-300"},{102,"}"}});return fields;
}
bool aciOpaque(const std::filesystem::path& path,bool binary) {
    const auto fields=materialBodyControls::physicalTags(path,binary);unsigned groups=0u,tails=0u;
    for(std::size_t i=0u;i<fields.size();++i) {
        if(fields[i]==std::make_pair(301,std::string("opaque-mline-tail")))++tails;
        if(fields[i]==std::make_pair(102,std::string("{ACI_META"))) {
            std::int64_t value=0;
            if(i+2u>=fields.size()||fields[i+1u].first!=62||!dx_raster_output::integer(fields[i+1u].second,value)
                ||value!=-300||fields[i+2u]!=std::make_pair(102,std::string("}")))return false;++groups;
        }
    }
    return groups==1u&&tails==1u;
}
