                if (group.code() == 72)
                    mapSources.push_back(group.i_val());
                else if (group.code() == 73)
                    mapProjections.push_back(group.i_val());
                else if (group.code() == 74)
                    mapTilings.push_back(group.i_val());
                else
                    mapAutoTransforms.push_back(group.i_val());
